// Krabičky bez výčitiek – 105 receptov
window.DB_KBV = [
{id:"kbv1",n:"Medové kuracie kúsky",c:"obed",p:5,s:3,k:450,pr:39,ca:59,f:5,tm:25,
ing:["450 g kuracích pŕs (očistených)","180 g ryže (v suchom stave, basmati)","150 g mrazenej zeleniny (hrášok a kukurica)","1 PL medu a 1 PL plnotučnej horčice","1 PL sójovej omáčky a 1 PL olivového oleja","1 ČL sušeného cesnaku, soľ, mleté čierne korenie"],
st:["Ryžu uvar v osolenej vode. Pred koncom prisyp mrazenú zeleninu. Sceď.","Kuracie prsia nakrájaj na kocky a zmiešaj s medom, horčicou, sójovkou a korením.","Na panvici rozohrej olej a mäso sprudka opekaj 8–10 minút do skaramelizovania.","Do každej krabičky daj tretinu ryže so zeleninou a vedľa nej medové kura."],
tip:"Nechaj jedlo pred zatvorením vychladnúť. Pri ohrievaní v práci pridaj do ryže lyžičku vody – para ryžu krásne oživí.",t:["mealprep","mikrovlnka"]},
{id:"kbv2",n:"Kuracie Fajitas",c:"obed",p:6,s:3,k:440,pr:38,ca:52,f:8,tm:20,
ing:["450 g kuracích pŕs","180 g jazmínovej ryže (v suchom stave)","1 červená a 1 žltá paprika, 1 červená cibuľa","1 PL olivového oleja a 2 ČL fajita/mexického korenia","soľ, korenie, šťava z 1 limetky"],
st:["Ryžu uvar v osolenej vode.","Kura, papriky aj cibuľu nakrájaj na tenké pásiky.","Na panvici opeč najprv kura s polovicou korenia (5 minút).","Pridaj zeleninu a zvyšok korenia, restuj ďalších 5–7 minút, kým zelenina nezmäkne, ale ostane chrumkavá.","Rozdeľ uvarenú ryžu, vedľa nej navrstvi fajitas zmes a všetko jemne pokvapkaj limetkou."],
tip:"V mikrovlnke ohrievaj aspoň 2 minúty a pred jedlom premiešaj.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv3",n:"Plnené kuracie prsia",c:"obed",p:7,s:3,k:480,pr:45,ca:46,f:12,tm:25,
ing:["3 kuracie prsia (cca 450 g)","100 g syra mozzarella light","40 g sušených paradajok","180 g celozrnného kuskusu","1 PL olivového oleja, soľ, sušená bazalka","hŕstka čerstvej rukoly"],
st:["Kuskus zalej vriacou vodou, nechaj 5 minút napučať, prekypri vidličkou a vmiešaj rukolu.","Do každého prsa narež kapsu, osoľ a okoreň. Naplň ju nakrájanou mozzarellou a sušenými paradajkami.","Na panvici opeč mäso sprudka z oboch strán (cca 3 minúty z každej).","Dopeč v rúre na 190 °C asi 10 minút.","Na dno daj ochutený kuskus s rukolou a naň polož jedno celé plnené kuracie prso."],
tip:"Pred ohrievaním si kuracie prso rovno v krabičke nakrájaj na plátky – mäso sa nevysuší.",t:["mealprep","mikrovlnka"]},
{id:"kbv4",n:"Krémové kuracie rezančeky",c:"obed",p:8,s:3,k:410,pr:39,ca:44,f:8,tm:35,
ing:["450 g kuracích pŕs","500 g zemiakov","300 g brokolice","100 ml smotany na varenie (10 %)","1 PL oleja, sušený cesnak, muškátový oriešok, soľ"],
st:["Zemiaky nakrájaj, pokvapkaj olejom, osoľ a upeč v rúre (200 °C, 25 minút).","Brokolicu uvar v osolenej vode domäkka.","Mäso nakrájaj na rezance, opeč na panvici a ochuť cesnakom, soľou a korením.","Zalej smotanou, pridaj muškátový oriešok a po zhustnutí vmiešaj brokolicu.","Na jednu stranu daj upečené zemiaky a na druhú krémovú mäsovú zmes."],
tip:"Zemiaky maj oddelené, aby nenasiakli omáčku skôr, než ich budeš jesť.",t:["mealprep","mikrovlnka"]},
{id:"kbv5",n:"Rýchle kuracie kari",c:"obed",p:9,s:3,k:460,pr:37,ca:48,f:13,tm:20,
ing:["450 g vykostených kuracích stehien","150 g ryže basmati","200 ml kokosového mlieka (light)","1 PL žltej alebo červenej kari pasty","1 menšia cuketa a 1 mrkva","1 ČL kokosového oleja, soľ"],
st:["Ryžu uvar klasicky v osolenej vode.","Kuracie stehná nakrájaj na menšie kúsky. Cuketu a mrkvu nakrájaj na polmesiačiky.","Na panvici rozohrej olej a orestuj kari pastu, aby uvoľnila vôňu (asi 30 sekúnd). Pridaj mäso a opekaj 5 minút.","Vhoď nakrájanú zeleninu, zalej kokosovým mliekom a dus 10 minút do zhustnutia.","Rozdeľ ryžu do nádob a zalej ju horúcim kari."],
tip:"Kari je najlepšie jedlo do krabičky vôbec – na druhý a tretí deň chutí ešte lepšie.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv6",n:"Grécke kuracie misky",c:"obed",p:10,s:3,k:420,pr:42,ca:38,f:11,tm:25,
ing:["450 g kuracích pŕs","150 g kuskusu","1 šalátová uhorka, 150 g cherry paradajok","50 g čiernych olív (bez kôstky)","1 PL gréckeho korenia (alebo oregána) a 1 PL olivového oleja","3 PL hotového tzatziki (alebo bieleho jogurtu s cesnakom)"],
st:["Kuskus zalej vriacou vodou, osoľ a nechaj 5 minút pod pokrievkou napučať.","Mäso nakrájaj na kocky, obaľ v gréckom korení a opeč na panvici s olejom dozlatista (cca 8 minút).","Uhorku, paradajky a olivy nakrájaj na menšie kúsky.","Na dno ulož kuskus, vedľa nakrájanú čerstvú zeleninu a navrch pridaj opečené mäso. Tzatziki daj do malej nádobky bokom."],
tip:"Chutí geniálne aj úplne studené ako sýty šalát.",t:["mealprep","studene"]},
{id:"kbv7",n:"Kuracie Teriyaki",c:"obed",p:11,s:3,k:410,pr:40,ca:45,f:6,tm:20,
ing:["450 g kuracích pŕs","180 g jazmínovej ryže","300 g brokolice","3 PL kvalitnej teriyaki omáčky","1 PL sezamového oleja (alebo olivového)","1 PL sezamových semienok"],
st:["Ryžu uvar klasicky v osolenej vode.","Brokolicu rozober na malé ružičky a zalej ich v miske vriacou vodou na 5 minút (blanšírovanie). Sceď.","Mäso nakrájaj na menšie kocky. Na panvici rozohrej olej a mäso sprudka opekaj, kým nezozlatne.","Pridaj teriyaki omáčku, stiahni oheň a nechaj omáčku obaliť mäso (1–2 minúty). Pridaj brokolicu a premiešaj.","Na dno ulož ryžu, pridaj lepkavé teriyaki kura s brokolicou a vrch posyp sezamom."],
tip:"Brokolicu nikdy nevar úplne domäkka – po zohriatí v mikrovlnke zmäkne do dokonalej konzistencie.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv8",n:"Citrónové kuracie prsia",c:"obed",p:12,s:3,k:390,pr:42,ca:35,f:9,tm:25,
ing:["450 g kuracích pŕs","150 g quinoy (v suchom stave)","200 g zelenej fazuľky (čerstvej alebo mrazenej)","šťava z 1/2 citróna a trochu kôry","1 PL olivového oleja, 1 ČL sušeného oregána","soľ a mleté čierne korenie"],
st:["Quinou prepláchni horúcou vodou a uvar v dvojnásobnom množstve osolenej vody (cca 15 min).","Zelenú fazuľku uvar v pare alebo vo vriacej vode domäkka (cca 5–7 min).","Kuracie prsia vcelku osoľ, okoreň a posyp oregánom. Opeč na panvici s olejom z oboch strán dozlatista. Ku koncu pokvapkaj citrónovou šťavou a posyp kôrou.","Upečené mäso nechaj minútu odpočinúť a nakrájaj na plátky.","Rozdeľ quinou, vedľa polož fazuľku a navrch plátky citrónového kurčaťa."],
tip:"Quinoa drží štruktúru lepšie ako ryža a nenasaje vlhkosť. Citrón funguje ako prírodný konzervant.",t:["mealprep","mikrovlnka"]},
{id:"kbv9",n:"Kuracie na šampiňónoch",c:"obed",p:13,s:3,k:380,pr:38,ca:40,f:8,tm:30,
ing:["450 g kuracích pŕs","150 g bulguru (v suchom stave)","250 g čerstvých šampiňónov","1/2 cibule","50 ml smotany na varenie (10 %)","1 PL oleja, 1 ČL drvenej rasce, soľ a korenie"],
st:["Bulgur zalej vriacou vodou, osoľ, prikry a nechaj 15 minút napučať.","Mäso nakrájaj na rezance. Šampiňóny na plátky a cibuľu nadrobno.","Na panvici orestuj cibuľku s olejom. Pridaj mäso a sprudka opeč.","Pridaj šampiňóny, rascu, soľ a korenie. Restuj, kým huby nepustia vodu a nezmäknú (asi 8 minút).","Zjemni smotanou, nechaj minútku prevrieť a odstav.","Do jednej polovice krabičky daj bulgur, do druhej mäso s hubami."],
tip:"Bulgur znesie ohrievanie oveľa lepšie ako zemiaky a v mikrovlnke sa z neho nestane kaša.",t:["mealprep","mikrovlnka"]},
{id:"kbv10",n:"Kuracie Caprese",c:"obed",p:14,s:3,k:420,pr:45,ca:30,f:12,tm:25,
ing:["450 g kuracích pŕs","150 g ryže (basmati)","150 g cherry paradajok","1 balenie (125 g) light mozzarelly","1 PL olivového oleja, sušená bazalka","balzamiková redukcia (na pokvapkanie)"],
st:["Ryžu uvar klasicky.","Kuracie prsia prekroj pozdĺžne na tenšie plátky. Osoľ a okoreň. Opeč ich na panvici z oboch strán dozlatista.","Upečené mäso ulož na plech. Na každý kúsok polož plátok mozzarelly a nakrájané cherry paradajky. Posyp bazalkou.","Daj zapiecť do rúry na 200 °C asi na 5 minút, kým sa syr neroztečie.","Rozdeľ ryžu, vedľa polož zapečené kuracie Caprese a pokvapkaj balzamikovou redukciou."],
tip:"Mozzarella na mäse pri ohrievaní vytvorí dokonalú šťavnatú čiapočku.",t:["mealprep","mikrovlnka"]},
{id:"kbv11",n:"BBQ kuracie misky",c:"obed",p:15,s:3,k:420,pr:45,ca:30,f:12,tm:20,
ing:["450 g kuracích pŕs","150 g ryže (alebo quinoy)","150 g kukurice (z konzervy)","100 g tmavej fazule (z konzervy)","3 PL kvalitnej BBQ omáčky","1 PL oleja, 1 ČL mletej papriky, soľ"],
st:["Ryžu uvar. Fazuľu a kukuricu prepláchni vodou a zmiešaj.","Kuracie prsia nakrájaj na kocky, osoľ a posyp mletou paprikou.","Na panvici ich sprudka opeč s olejom domäkka.","Keď je mäso hotové, stiahni oheň, pridaj BBQ omáčku a nechaj ju na mäse lepkavo zredukovať (1 minúta).","Do krabičky ulož ryžu, vedľa mix kukurice a fazule a do tretej tretiny lepkavé BBQ mäso."],
tip:"BBQ omáčka vydrží v chladničke dni a mäso nevyschne.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv12",n:"Kuracie na paprike",c:"obed",p:16,s:3,k:450,pr:40,ca:48,f:11,tm:30,
ing:["450 g vykostených kuracích stehien","500 g zemiakov (alebo 180 g celozrnných cestovín)","1 cibuľa","2 PL mletej sladkej papriky","100 ml smotany na varenie (10 %)","1 PL oleja, soľ"],
st:["Zemiaky uvar v osolenej vode domäkka (ak chceš cestoviny, uvar tie).","Mäso nakrájaj na kocky. Cibuľu nadrobno.","Na panvici orestuj cibuľu. Pridaj mäso a opeč ho.","Stiahni plameň na minimum, zasyp mletou paprikou, rýchlo premiešaj a ihneď podlej vodou (asi 150 ml), aby paprika nezhorkla. Dus 15 minút.","Vlej smotanu, nechaj prevrieť a omáčka je hotová.","Rozdeľ uvarené zemiaky a prelej ich krémovým paprikášom s mäsom."],
tip:"Omáčka pri chladnutí zhustne, no po ohriatí bude opäť krásne hladká.",t:["mealprep","mikrovlnka"]},
{id:"kbv13",n:"Arašidové kuracie kúsky",c:"obed",p:17,s:3,k:480,pr:42,ca:40,f:16,tm:25,
ing:["450 g kuracích pŕs","150 g jazmínovej ryže","200 g brokolice alebo zelenej fazuľky","2 PL 100 % arašidového masla","1 PL sójovej omáčky a 1 PL medu","1 PL oleja, trochu horúcej vody"],
st:["Ryžu uvar, brokolicu jemne oblanšíruj vo vriacej vode.","V malej miske vymiešaj arašidové maslo, sójovku, med a trochu horúcej vody, kým nevznikne hladká krémová omáčka.","Mäso nakrájaj na kúsky a opeč na panvici s olejom.","Ku koncu vylej na mäso arašidovú omáčku a nechaj ju minútku zredukovať.","Na dno ulož ryžu a brokolicu, navrch pridaj kuracie kúsky v arašidovej omáčke."],
tip:"Arašidové maslo v omáčke nepustí vodu. V lete môžeš jedlo zjesť aj studené.",t:["mealprep","mikrovlnka"]},
{id:"kbv14",n:"Zdravé Cordon Bleu",c:"obed",p:18,s:3,k:460,pr:45,ca:40,f:12,tm:35,
ing:["450 g kuracích pŕs","500 g zemiakov","60 g kvalitnej šunky (s vysokým podielom mäsa)","60 g tvrdého syra (Eidam alebo Gouda)","1 PL oleja, soľ, obľúbené korenie na kura"],
st:["Zemiaky nakrájaj na plátky, osoľ, pokvapkaj olejom a daj piecť na 200 °C (cca 25 minút).","Mäso nakrájaj na širšie plátky, osoľ a okoreň.","Namiesto klasického plnenia a vyprážania urob rozloženú verziu: plátky mäsa ulož na plech k zemiakom (asi 10 minút pred koncom pečenia).","Keď je mäso takmer upečené, polož na každý kúsok plátok šunky a plátok syra. Nechaj v rúre dopiecť, kým sa syr neroztopí.","Rozdeľ pečené zemiaky a na ne polož zapečené mäso."],
tip:"Tým, že Cordon Bleu nevyprážame v strúhanke, nebude po ohriatí v mikrovlnke mokrý.",t:["mealprep","mikrovlnka"]},
{id:"kbv15",n:"Sladkokyslé kuracie kúsky",c:"obed",p:19,s:3,k:430,pr:38,ca:55,f:6,tm:25,
ing:["450 g kuracích pŕs","180 g jazmínovej ryže","1 červená paprika a 1/2 menšieho ananásu (alebo menšia konzerva)","3 PL nesladeného paradajkového pretlaku","1 PL medu (alebo ananásovej šťavy), 1 PL sójovej omáčky","1 PL oleja"],
st:["Ryžu uvar klasicky vo vode.","Mäso, papriku a ananás nakrájaj na približne rovnako veľké kocky.","V miske zmiešaj pretlak, med, sójovku a trošku vody – vznikne sladkokyslá omáčka.","Na panvici rozohrej olej, opeč kuracie mäso. Keď zozlatne, pridaj papriku a ananás. Restuj 3 minúty.","Vylej omáčku a dus ešte 2 minúty, kým jedlo nezhustne.","Polovicu krabičky naplň ryžou a druhú sladkokyslým kuraťom s ananásom."],
tip:"Ananás udrží jedlo šťavnaté počas celej doby skladovania.",t:["mealprep","mikrovlnka"]},

{id:"kbv16",n:"Talianske guľky",c:"obed",p:21,s:3,k:490,pr:35,ca:55,f:12,tm:30,
ing:["450 g mletého hovädzieho mäsa (chudého)","180 g celozrnných špagiet","300 ml pasírovaných paradajok (passata)","1 strúčik cesnaku, 1 PL sušeného oregana","1 PL olivového oleja, soľ, čierne korenie","30 g nastrúhaného parmezánu"],
st:["Špagety uvar v osolenej vode.","Z mletého mäsa, soli a korenia vytvaruj malé guličky (cca 12–15 kusov).","Na panvici s olejom ich opeč dozlatista. Pridaj pretlačený cesnak a oregano.","Zalej paradajkovou passatou a dus 10 minút, kým omáčka nezhustne.","Rozdeľ špagety, prelej ich omáčkou s guľkami a posyp parmezánom."],
tip:"Špagety pred vložením do krabičky premiešaj s kvapkou oleja, aby sa nezlepili.",t:["mealprep","mikrovlnka"]},
{id:"kbv17",n:"Morčacia sekaná",c:"obed",p:22,s:3,k:420,pr:38,ca:42,f:8,tm:40,
ing:["450 g mletých morčacích pŕs","1 stredná mrkva (nastrúhaná najemno)","500 g zemiakov","1 vajíčko","1 PL ovsených vločiek, soľ, majoránka","200 g zelených fazuliek (príloha)"],
st:["Zemiaky nakrájaj na kocky a upeč v rúre (200 °C, 25 minút). Fazuľky krátko uvar v pare.","Mleté mäso zmiešaj s mrkvou, vajíčkom, vločkami a majoránkou.","Vytvaruj menší bochník a peč v rúre spolu so zemiakmi (cca 30 minút).","Sekanú nakrájaj na hrubšie plátky, rozdeľ zemiaky a fazuľky."],
tip:"Mrkva v mäse zabezpečí, že morčacie prsia nebudú suché ani na tretí deň.",t:["mealprep","mikrovlnka"]},
{id:"kbv18",n:"Chili con Carne",c:"obed",p:23,s:3,k:460,pr:32,ca:58,f:11,tm:25,
ing:["450 g mletého hovädzieho mäsa","150 g ryže (basmati)","1 plechovka červenej fazule (400 g)","100 g kukurice","200 ml pasírovaných paradajok","čili, rímska rasca, soľ"],
st:["Ryžu uvar.","Na panvici orestuj mäso, pridaj koreniny, fazuľu, kukuricu a paradajky.","Dus 15 minút, kým chute nesplynú a omáčka nezhustne.","Polovica krabičky ryža, druhá polovica chili zmes."],
tip:"Toto jedlo chutí po rozležaní v chladničke ešte lepšie. Ryža nasaje pikantnú šťavu.",t:["mealprep","mikrovlnka","pikantne"]},
{id:"kbv19",n:"Ázijské guľky",c:"obed",p:24,s:3,k:440,pr:36,ca:48,f:10,tm:25,
ing:["450 g mletého bravčového alebo hovädzieho mäsa","180 g jazmínovej ryže","2 PL sójovej omáčky, 1 ČL mletého zázvoru","1 strúčik cesnaku","1 PL medu, sezamové semienka"],
st:["Ryžu uvar. Mäso zmiešaj so zázvorom a cesnakom, vytvaruj guličky a upeč v rúre (200 °C, 15 minút).","Na panvici zohrej sójovku s medom, pridaj upečené guľky a obaľ ich v lepkavej omáčke.","Ryža a navrch glazované guľky posypané sezamom."],
tip:"Guľky si zachovajú textúru aj po ohriatí, vďaka medovej glazúre nevyschnú.",t:["mealprep","mikrovlnka"]},
{id:"kbv20",n:"Plnená paprika",c:"obed",p:25,s:3,k:410,pr:30,ca:45,f:12,tm:45,
ing:["450 g mletého mäsa mix (hovädzie/bravčové)","3 veľké papriky","80 g ryže (nevarenej, do náplne)","400 ml paradajkovej šťavy","soľ, čierne korenie, štipka cukru (na omáčku)"],
st:["Ryžu predvar do polomäkka a zmiešaj s mäsom, soľou a korením.","Papriky očisti a naplň mäsovou zmesou.","Vlož do hrnca s paradajkovou šťavou a dus 30–40 minút domäkka.","Do každej krabičky jedna plnená paprika a bohatá porcia omáčky."],
tip:"Paprika chráni mäso pred vysušením v mikrovlnke.",t:["mealprep","mikrovlnka"]},
{id:"kbv21",n:"Švédske guľky",c:"obed",p:26,s:3,k:480,pr:34,ca:44,f:18,tm:35,
ing:["450 g mletého mäsa mix","500 g zemiakov (na kašu)","100 ml smotany na varenie (10%)","1 ČL brusnicového džemu (do každej krabičky)","nové korenie, soľ, mleté čierne korenie"],
st:["Zemiaky uvar a popuč na kašu s trochou mlieka.","Z mäsa a korenia urob guličky, opeč ich na panvici.","Pridaj smotanu a nechaj krátko prevrieť, kým nevznikne krémová omáčka.","Zemiaková kaša, guľky s omáčkou a lyžička brusníc bokom."],
tip:"Zemiakovú kašu v krabičke uhlaď, aby omáčka ostala na povrchu a nepremočila ju celú.",t:["mealprep","mikrovlnka"]},
{id:"kbv22",n:"Mäsové Bolognese",c:"obed",p:27,s:3,k:480,pr:34,ca:44,f:18,tm:25,
ing:["450 g mletého hovädzieho mäsa","180 g celozrnných penne","300 ml paradajkovej passaty","1 cibuľa, 1 mrkva (nastrúhaná)","talianske bylinky, soľ"],
st:["Cestoviny uvar.","Na panvici orestuj cibuľu, mäso a mrkvu. Pridaj passatu a bylinky.","Dus 15 minút.","Cestoviny zmiešaj priamo s omáčkou, aby v chladničke neschli."],
tip:"Mrkva v omáčke dodá sladkosť bez cukru a po 2 dňoch chutia cestoviny ešte lepšie.",t:["mealprep","mikrovlnka"]},
{id:"kbv23",n:"Burger v miske",c:"obed",p:28,s:3,k:430,pr:35,ca:30,f:18,tm:20,
ing:["450 g mletého hovädzieho mäsa","400 g batátov (sladkých zemiakov)","150 g ľadového šalátu, cherry paradajky","3 kyslé uhorky","1 PL horčice (na mäso)"],
st:["Batáty nakrájaj na hranolky a upeč v rúre (200 °C, 20 minút).","Z mäsa vytvaruj 3 väčšie placky a opeč na panvici ako klasický burger.","Na jednu stranu batáty, na druhú čerstvý šalát s paradajkami a uhorkou, navrch polož mäso."],
tip:"Mäso ohrievaj spolu s batátmi, ale šalát a uhorky si pred ohrevom vyber na tanier.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv24",n:"Marocké guľky",c:"obed",p:29,s:3,k:440,pr:32,ca:48,f:12,tm:30,
ing:["450 g mletého hovädzieho alebo jahňacieho mäsa","150 g bulguru","1 PL paradajkového pretlaku","rímska rasca, škorica, mletý koriander","100 g cíceru (z konzervy)"],
st:["Bulgur uvar.","Mäso zmiešaj s koreninami, vytvaruj guľky a opeč.","Pridaj pretlak, cícer a trocha vody, nechaj prebublať 5 minút.","Bulgur a navrch aromatické orientálne guľky s cícerom."],
tip:"Exotické koreniny ako škorica a koriander robia jedlo zaujímavým aj za studena.",t:["mealprep","mikrovlnka"]},
{id:"kbv25",n:"Guľky s kôprom",c:"obed",p:30,s:3,k:450,pr:34,ca:42,f:15,tm:30,
ing:["450 g mletého morčacieho mäsa","500 g zemiakov","100 ml smotany na varenie (10%)","veľký zväzok čerstvého kôpru","štipka octu a cukru (na doladenie omáčky)"],
st:["Zemiaky uvar.","Z mäsa urob guľky a uvar ich vo vode (vývare) domäkka.","Vývar zjemni smotanou, pridaj nasekaný kôpor a dochuť.","Zemiaky, guľky a zaliať jemnou kôprovou omáčkou."],
tip:"Ak omáčka v chladničke príliš zhustne, prilej pred ohrevom lyžicu mlieka.",t:["mealprep","mikrovlnka"]},
{id:"kbv26",n:"Zapekaná sekaná",c:"obed",p:31,s:3,k:460,pr:35,ca:44,f:14,tm:35,
ing:["450 g mletého mäsa mix","150 g mrazenej kukurice a hrášku","180 g ryže","50 g tvrdého syra (na posypanie)"],
st:["Ryžu uvar spolu so zeleninou.","Mleté mäso rozprestri na malý plech a upeč dozlatista (200 °C, 20 minút).","Na upečené mäso daj vrstvu ryže so zeleninou, posyp syrom a daj zapiecť na 5 minút.","Tento nákyp nakrájaj na tri časti."],
tip:"Syrová krusta navrchu udrží vlhkosť v ryži aj v mäse pod ňou.",t:["mealprep","mikrovlnka"]},
{id:"kbv27",n:"Karí guľky",c:"obed",p:32,s:3,k:440,pr:36,ca:46,f:12,tm:25,
ing:["450 g mletého morčacieho mäsa","150 g ryže (basmati)","200 ml kokosového mlieka (light)","1 PL žltej karí pasty","špenátové listy (do omáčky)"],
st:["Ryžu uvar.","Z mäsa urob guľky a opeč na panvici.","Pridaj karí pastu, kokosové mlieko a špenát. Nechaj 5 minút prevrieť.","Ryža a preliať krémovými exotickými guľkami."],
tip:"Kokosové mlieko je veľmi stabilné pri ohrievaní a dodá morčacím mäsu potrebný tuk.",t:["mealprep","mikrovlnka","pikantne"]},
{id:"kbv28",n:"Tex-Mex panvica",c:"obed",p:33,s:3,k:430,pr:33,ca:48,f:12,tm:20,
ing:["450 g mletého hovädzieho mäsa","180 g celozrnných makarónov/kolienok","100 g kukurice, 100 g čiernej fazule","salsa omáčka (pálivá podľa chuti)","jarná cibuľka na ozdobu"],
st:["Cestoviny uvar.","Mäso orestuj, pridaj kukuricu, fazuľu a salsu.","Všetko zmiešaj v jednej panvici aj s uvarenými cestovinami.","Rovnomerné porcie posypané jarnou cibuľkou."],
tip:"Salsu používaj radšej redšiu, aby cestoviny v chladničke neostali suché.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv29",n:"Mäsové košíčky",c:"obed",p:34,s:3,k:390,pr:36,ca:25,f:15,tm:30,
ing:["450 g mletého morčacieho mäsa","1 vajíčko, 1 PL paradajkového pretlaku","300 g varenej brokolice (ako príloha)","3 plátky syra (na vrch košíčkov)","forma na muffiny"],
st:["Mäso zmiešaj s vajíčkom a pretlakom. Natlač do foriem na muffiny (urob 6–9 košíčkov).","Peč pri 190 °C cca 20 minút. Na záver polož na každý kúsok syra.","Do každej krabičky 2–3 košíčky a porcia brokolice."],
tip:"Košíčky sú skvelé na kontrolu porcií a môžeš ich jesť aj studené ako snack.",t:["mealprep","mikrovlnka"]},
{id:"kbv30",n:"Guľky v paradajke",c:"obed",p:35,s:3,k:420,pr:32,ca:46,f:10,tm:25,
ing:["450 g mletého hovädzieho mäsa","150 g ryže","300 ml paradajkového džúsu","štipka škorice a klinčeka"],
st:["Ryžu uvar.","Z mäsa urob guľky a uvar ich priamo v paradajkovej šťave ochutenej koreninami (cca 15 minút).","Ryža a zaliať paradajkovou omáčkou s guľkami."],
tip:"Paradajková omáčka udržuje mäso svieže niekoľko dní.",t:["mealprep","mikrovlnka"]},

{id:"kbv31",n:"Tuniakové penne",c:"obed",p:37,s:3,k:410,pr:32,ca:50,f:9,tm:15,
ing:["200 g celozrnných penne","2 konzervy tuniaka vo vlastnej šťave (spolu cca 240 g po odkvapkaní)","100 g kukurice (z konzervy)","1 červená cibuľa","150 g bieleho gréckeho jogurtu","1 PL plnotučnej horčice, soľ, mleté čierne korenie"],
st:["Cestoviny uvar v osolenej vode al dente. Sceď ich a nechaj mierne vychladnúť.","Cibuľu nakrájaj na úplne jemné kocky. V miske zmiešaj grécky jogurt, horčicu, soľ a korenie na svieži dresing.","Vychladnuté cestoviny jemne zmiešaj s tuniakom, kukuricou, cibuľou a dresingom.","Hotové krémové penne rovnomerne nalož do krabičiek."],
tip:"Ideálny studený obed – v práci ich nemusíš vôbec ohrievať.",t:["mealprep","rychle","studene"]},
{id:"kbv32",n:"Kuracie pesto",c:"obed",p:38,s:3,k:460,pr:38,ca:45,f:14,tm:20,
ing:["200 g cestovín (napríklad fusilli)","400 g kuracích pŕs","3 PL kvalitného bazalkového pesta","150 g cherry paradajok","1 PL olivového oleja, soľ, mleté čierne korenie"],
st:["Cestoviny uvar v osolenej vode. Pred zliatím si odlož asi pol deci vody z varenia.","Kuracie prsia nakrájaj na kocky, osoľ a okoreň. Opeč ich na panvici s olivovým olejom dozlatista (cca 8 minút).","Do panvice ku kuraťu pridaj uvarené cestoviny, pesto a trochu odloženej vody. Dobre premiešaj.","Pridaj na polovice prekrojené cherry paradajky a minútku prehrej.","Rozdeľ pesto cestoviny s mäsom rovnomerne do troch nádob."],
tip:"Olej v peste zaručí, že sa cestoviny v chladničke nezlepia.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv33",n:"Špenátové gnocchi",c:"obed",p:39,s:3,k:420,pr:25,ca:55,f:10,tm:15,
ing:["400 g zemiakových gnocchi (chladených)","200 g čerstvého baby špenátu","150 g syra ricotta","1 strúčik cesnaku","1 PL masla, soľ, čierne korenie, muškátový oriešok"],
st:["Gnocchi uvar vo vriacej osolenej vode, kým nevyplávajú na povrch (asi 2 minúty). Sceď ich.","Na veľkej panvici rozohrej maslo a pridaj pretlačený cesnak. Hneď nato vhoď čerstvý špenát a nechaj ho zvädnúť (asi 1 minúta).","Do panvice vmiešaj ricottu, pridaj soľ, korenie a štipku muškátového orieška.","Uvarené gnocchi vhoď do omáčky a zľahka premiešaj.","Gnocchi rovnomerne naporcuj."],
tip:"Ricotta je ľahšia ako smotana a po ohriatí získa vláčnu textúru.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv34",n:"Syrové makaróny",c:"obed",p:40,s:3,k:440,pr:26,ca:52,f:14,tm:25,
ing:["200 g makarónov alebo kolienok","150 g kvalitného čedaru (nastrúhaného)","150 g maslovej tekvice (uvarenej a popučenej na pyré)","100 ml polotučného mlieka","soľ, štipka údenej papriky"],
st:["Cestoviny uvar v osolenej vode domäkka a sceď.","V hrnci na miernom ohni zohrej mlieko a vmiešaj do neho tekvicové pyré.","Postupne prisypávaj nastrúhaný čedar a miešaj, kým sa syr úplne neroztopí na hladkú omáčku. Dochuť soľou a údenou paprikou.","Uvarené makaróny vmiešaj priamo do syrovej omáčky."],
tip:"Tekvicové pyré je tajná ingrediencia – omáčka zostane tekutá a po zohriatí nestvrdne.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv35",n:"Paradajkové fusilli",c:"obed",p:41,s:3,k:400,pr:22,ca:55,f:10,tm:30,
ing:["200 g celozrnných fusilli","400 g cherry paradajok","150 g mini mozzarelly (perličky)","2 strúčiky cesnaku","1 PL olivového oleja, čerstvá bazalka, soľ"],
st:["Cherry paradajky v celku polož na plech, pridaj celé strúčiky cesnaku, pokvapkaj olejom, osoľ a upeč v rúre (200 °C, 20 minút).","Zatiaľ uvar cestoviny.","Upečený cesnak roztlač vidličkou priamo na plechu a zmiešaj so šťavou z paradajok.","Cestoviny zmiešaj s pečenými paradajkami, šťavou a pridaj hrsť natrhanej bazalky.","Cestoviny nalož do nádob a navrch rozsyp guličky mini mozzarelly."],
tip:"Mozzarellu pridávaj vždy navrch až pri ukladaní do krabičiek.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv36",n:"Lososové farfalle",c:"obed",p:42,s:3,k:450,pr:26,ca:50,f:16,tm:15,
ing:["200 g cestovín farfalle (mašličky)","150 g údeného lososa","100 g krémového syra (typu Lučina alebo Philadelphia light)","1 PL citrónovej šťavy","hrsť čerstvého kôpru, mleté čierne korenie"],
st:["Cestoviny uvar v osolenej vode. Tesne pred zliatím odober malú šálku (cca 50 ml) horúcej vody.","Údeného lososa nakrájaj na menšie pásiky.","Horúce cestoviny vráť do hrnca. Pridaj krémový syr a horúcu vodu z cestovín. Miešaj, kým sa syr nerozpustí.","Pridaj kúsky lososa, citrónovú šťavu a nasekaný kôpor. Jemne premiešaj."],
tip:"Pri ohrievaní zníž výkon mikrovlnky na stredný (cca 600 W), aby sa losos nevysušil.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv37",n:"Feta cestoviny",c:"obed",p:43,s:3,k:430,pr:20,ca:52,f:15,tm:35,
ing:["200 g obľúbených cestovín","1 celý blok syra feta (cca 150 g)","400 g cherry paradajok","1 PL olivového oleja","2 strúčiky cesnaku, oregáno, mleté čierne korenie"],
st:["Do stredu menšieho plechu polož blok fety. Okolo neho rozsyp cherry paradajky a celé strúčiky cesnaku.","Pokvapkaj olivovým olejom, posyp oregánom a korením. Peč pri 200 °C asi 25–30 minút.","Medzitým uvar cestoviny a sceď ich.","Misku vyber z rúry a vidličkou roztlač upečenú fetu, cesnak aj paradajky do jednoliatej omáčky.","Zmiešaj omáčku s uvarenými cestovinami."],
tip:"Feta po upečení funguje ako spojivo – omáčka výborne znáša chlad aj ohrev.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv38",n:"Hubové tagliatelle",c:"obed",p:44,s:3,k:390,pr:15,ca:55,f:12,tm:20,
ing:["200 g širokých rezancov (tagliatelle)","300 g čerstvých šampiňónov","1 cibuľa, 1 strúčik cesnaku","100 ml smotany na varenie (10 %)","1 PL olivového oleja, čerstvý tymian, soľ, korenie"],
st:["Tagliatelle uvar v osolenej vode domäkka.","Cibuľu nakrájaj nadrobno, šampiňóny na plátky.","Na panvici rozohrej olej, orestuj cibuľku s cesnakom. Pridaj šampiňóny a sprudka opekaj, kým nepustia šťavu a nezískajú hnedú farbu.","Pridaj lístky tymianu, soľ a korenie. Zalej smotanou a nechaj 2 minúty zredukovať.","Cestoviny vmiešaj do hubovej omáčky."],
tip:"Široké rezance do seba pri skladovaní vtiahnu časť smotany – na druhý deň budú plné chuti.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv39",n:"Cuketové špagety",c:"obed",p:45,s:3,k:380,pr:35,ca:40,f:9,tm:20,
ing:["120 g klasických špagiet","300 g cukety (na špiralizovanie alebo nastrúhanie)","400 g kuracích pŕs","2 strúčiky cesnaku","1 PL olivového oleja, soľ, čili vločky","20 g parmezánu na posypanie"],
st:["Špagety uvar klasicky vo vode.","Z cukety vytvor pomocou škrabky alebo špiralizéra dlhé zoodles.","Kuracie prsia nakrájaj na malé kocky a sprudka ich opeč na oleji. Ku koncu pridaj cesnak a čili vločky.","K mäsu vhoď surové cuketové špagety a opekaj ich maximálne 1–2 minúty.","Do panvice vmiešaj aj klasické uvarené špagety, premiešaj a odstav. Posyp parmezánom."],
tip:"Kombinácia pol na pol ťa zasýti, no ušetríš veľa sacharidov a kalórií.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv40",n:"Cestovinový šalát",c:"obed",p:46,s:3,k:390,pr:25,ca:48,f:11,tm:15,
ing:["200 g cestovín (ideálne farfalle alebo penne)","150 g chudej šunky v celku (nakrájanej na kocky)","100 g syra ementál alebo gouda (na kocky)","1 červená paprika","150 g bieleho gréckeho jogurtu","1 ČL byliniek (pažítka/kôpor), soľ, mleté čierne korenie"],
st:["Cestoviny uvar, sceď a poriadne prepláchni studenou vodou, aby úplne vychladli.","V miske vymiešaj jogurt s bylinkami, soľou a korením.","K dresingu pridaj studené cestoviny, šunku, syr a červenú papriku. Dôkladne premiešaj.","Nalož šalát rovnomerne do krabičiek."],
tip:"Tento obed do mikrovlnky nepatrí – je to prvá pomoc počas hektických dní.",t:["mealprep","rychle","studene"]},
{id:"kbv41",n:"Zapekané penne",c:"obed",p:47,s:3,k:440,pr:30,ca:48,f:14,tm:35,
ing:["200 g celozrnných penne","250 g cottage syra (light)","200 ml pasírovaných paradajok (passata)","100 g syra mozzarella (strúhaná)","2 hrste čerstvého baby špenátu","1 strúčik cesnaku, talianske bylinky, soľ"],
st:["Cestoviny uvar v osolenej vode (nechaj ich tvrdšie, v rúre ešte dôjdu). Sceď.","Vo veľkej miske zmiešaj cestoviny, cottage syr, passatu, pretlačený cesnak, bylinky a špenát.","Celú zmes prelož do menšej zapekacej misy a vrch posyp strúhanou mozzarellou.","Peč v rúre pri 200 °C asi 15 minút, kým syr nevytvorí zlatistú kôrku.","Zapekané cestoviny rozkroj na 3 rovnaké časti."],
tip:"Syrová krusta udrží vo vnútri všetku vlhkosť – po zohriatí sú neuveriteľne šťavnaté.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv42",n:"Avokádové cestoviny",c:"obed",p:48,s:3,k:410,pr:18,ca:45,f:16,tm:35,
ing:["200 g cestovín (napr. farfalle alebo vretená)","1 veľké, veľmi zrelé avokádo","150 g mozzarelly light (alebo kuracej šunky)","150 g cherry paradajok","šťava z 1/2 limetky, 1 strúčik cesnaku","čerstvý koriander alebo bazalka, soľ, korenie"],
st:["Cestoviny uvar v osolenej vode a prepláchni studenou vodou, aby úplne vychladli.","V mixéri (alebo vidličkou) roztlač avokádo dohladka. Pridaj limetkovú šťavu, cesnak, soľ a korenie.","Studené cestoviny zmiešaj s avokádovým krémom.","Pridaj na polovice nakrájané cherry paradajky a na kocky nakrájanú mozzarellu."],
tip:"Limetková šťava zabráni zhnednutiu avokáda. Tento obed sa neohrieva.",t:["mealprep","studene","bezmasa"]},
{id:"kbv43",n:"Morčacie rigatoni",c:"obed",p:49,s:3,k:450,pr:36,ca:50,f:12,tm:25,
ing:["200 g hrubších cestovín (rigatoni alebo penne)","400 g mletého morčacieho mäsa","200 ml pasírovaných paradajok","50 ml smotany na varenie (10 %)","1 PL olivového oleja, 1/2 cibule","talianske korenie, soľ"],
st:["Cestoviny uvar. Hrubé rigatoni sú ideálne, lebo omáčka sa dostane dovnútra.","Na panvici orestuj nakrájanú cibuľu. Pridaj mleté morčacie mäso a sprudka ho opeč.","Zalej pasírovanými paradajkami, pridaj korenie, soľ a dus 10 minút.","Na záver vlej smotanu a nechaj minútku prebublať.","Zmiešaj cestoviny priamo s omáčkou v panvici."],
tip:"Rigatoni uzamknú omáčku vo svojich trubičkách – jedlo sa nerozmočí.",t:["mealprep","mikrovlnka"]},
{id:"kbv44",n:"Zelené špagety",c:"obed",p:50,s:3,k:380,pr:25,ca:55,f:8,tm:20,
ing:["200 g špagiet (ideálne celozrnných)","150 g mrazeného hrášku","150 g brokolice","200 g cottage syra","1 strúčik cesnaku, šťava z 1/4 citróna","20 g parmezánu, soľ, čierne korenie"],
st:["Do veľkého hrnca daj variť vodu. Vlož špagety. Keď im chýbajú 3 minúty do konca, prihoď hrášok a malé ružičky brokolice.","Pred zliatím si odober šálku horúcej vody (cca 100 ml).","Do mixéra daj cottage syr, cesnak, citrónovú šťavu, soľ, korenie a polovicu odloženej vody. Rozmixuj na hladkú smotanovú omáčku.","Špagety so zeleninou vráť do hrnca a prelej ich omáčkou.","Nalož do krabičiek a posyp parmezánom."],
tip:"Rozmixovaný cottage syr vytvorí textúru pravej smotany, ale s dávkou bielkovín.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv45",n:"Stroganov cestoviny",c:"obed",p:51,s:3,k:460,pr:35,ca:48,f:14,tm:25,
ing:["200 g cestovín (ideálne široké rezance)","400 g kuracích pŕs","200 g čerstvých šampiňónov","1 cibuľa, 2 väčšie kyslé uhorky","1 PL plnotučnej horčice","100 g kyslej smotany (light), 1 PL oleja, soľ, korenie"],
st:["Cestoviny uvar domäkka. Kyslé uhorky nakrájaj na úplne drobné kocky.","Na panvici orestuj cibuľku s olejom. Pridaj na rezance nakrájané mäso a opeč ho.","Pridaj nakrájané šampiňóny a opekaj, kým huby nezmäknú.","Stiahni oheň na minimum. Pridaj horčicu, uhorky, kyslú smotanu, soľ a korenie. Premiešaj a už nevar.","Uvarené cestoviny zmiešaj priamo s omáčkou z panvice."],
tip:"Horčica a kyslé uhorky sa v chladničke po dni nádherne preležia a zvýraznia.",t:["mealprep","mikrovlnka"]},

{id:"kbv46",n:"Cícerové kari",c:"obed",p:53,s:3,k:410,pr:15,ca:55,f:14,tm:20,
ing:["1 konzerva cíceru (cca 240 g po odkvapkaní)","150 g ryže (basmati alebo jazmínová)","200 ml kokosového mlieka (light)","1 konzerva krájaných paradajok (400 g)","1 PL červenej alebo žltej kari pasty","2 hrste čerstvého baby špenátu","1 PL oleja, štipka soli"],
st:["Ryžu uvar v osolenej vode podľa návodu.","Na hlbšej panvici rozohrej olej a minútku na ňom orestuj kari pastu.","Pridaj prepláchnutý cícer, krájané paradajky a kokosové mlieko. Nechaj prebublávať 10 minút.","Odstav z ohňa, vhoď baby špenát a zľahka premiešaj.","Do jednej polovice krabičky daj ryžu, do druhej cícerové kari."],
tip:"Strukoviny v omáčkach sú na meal prep najlepšie – na tretí deň chutia najlepšie.",t:["mealprep","mikrovlnka","rychle","pikantne","bezmasa"]},
{id:"kbv47",n:"Chrumkavé tofu",c:"obed",p:54,s:3,k:390,pr:22,ca:45,f:12,tm:20,
ing:["2 balenia bieleho pevného tofu (spolu cca 360–400 g)","150 g ryže alebo quinoy","300 g brokolice","2 PL kukuričného škrobu","3 PL sójovej omáčky, 1 PL medu","1 PL sezamového alebo olivového oleja"],
st:["Tofu poriadne osuš papierovými utierkami (ideálne ho chvíľu zaťaž). Nakrájaj ho na kocky.","Kocky tofu hoď do misky, zasyp kukuričným škrobom a pretrep.","Na panvici rozohrej olej a tofu opekaj zo všetkých strán dochrumkava (cca 8–10 minút).","Zatiaľ uvar ryžu a brokolicu oblanšíruj vo vriacej vode (cca 4 minúty).","K opečenému tofu vylej sójovú omáčku zmiešanú s medom. Rýchlo premiešaj – omáčka zhustne.","Rozdeľ ryžu, brokolicu a pridaj lepkavé tofu."],
tip:"Kukuričný škrob je tajomstvo chrumkavého tofu – udrží štruktúru aj po ohriatí.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv48",n:"Šošovicový dahl",c:"obed",p:55,s:3,k:380,pr:18,ca:52,f:8,tm:25,
ing:["200 g červenej šošovice (v suchom stave)","150 g ryže (basmati)","200 ml pasírovaných paradajok (passata)","1 menšia cibuľa a 1 strúčik cesnaku","1 PL korenia Garam Masala (alebo kari)","1 PL oleja, soľ"],
st:["Ryžu uvar v osolenej vode. Červenú šošovicu prepláchni v sitku.","Na hlbšej panvici orestuj na oleji nakrájanú cibuľu a cesnak. Pridaj Garam Masala a miešaj, kým nezačne voňať.","Pridaj prepláchnutú šošovicu, zalej ju passatou a zhruba 300 ml vody.","Osoľ a nechaj dusiť pod pokrievkou asi 15–20 minút, kým šošovica nevytvorí hustú kašu.","Do krabičiek naber ryžu a šošovicový dahl."],
tip:"Ak sa ti dahl zdá príliš hustý, pri ohrievaní vmiešaj 2 lyžice teplej vody.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv49",n:"Mexická fazuľa",c:"obed",p:56,s:3,k:420,pr:16,ca:60,f:8,tm:15,
ing:["2 konzervy červenej fazule (spolu cca 480 g po odkvapkaní)","150 g kukurice (z konzervy)","150 g ryže (v suchom stave)","200 ml paradajkového pyré","1 avokádo (pridá sa až neskôr)","1 ČL mletej sladkej papriky, štipka čili, soľ"],
st:["Ryžu uvar klasicky vo vode.","Fazuľu a kukuricu dôkladne prepláchni a daj na panvicu.","Zalej ich paradajkovým pyré, pridaj soľ, mletú papriku a čili.","Nechaj 5–7 minút prevrieť, kým chute nesplynú.","Na dno daj ryžu a na ňu navrstvi fazuľovo-kukuričnú zmes."],
tip:"Avokádo NIKDY nekrájaj do krabičiek dopredu – zober si ho do práce vcelku.",t:["mealprep","mikrovlnka","rychle","pikantne","bezmasa"]},
{id:"kbv50",n:"Tofu praženica",c:"obed",p:57,s:3,k:380,pr:25,ca:40,f:14,tm:20,
ing:["2 balenia bieleho (alebo údeného) tofu (spolu cca 360–400 g)","400 g batátov (sladkých zemiakov)","1 červená paprika, 1 cibuľa","1 ČL kurkumy","1 PL oleja, soľ (ideálne čierna soľ Kala Namak), korenie"],
st:["Batáty ošúp, nakrájaj na menšie kocky, jemne osoľ a upeč v rúre (200 °C na 20 minút).","Tofu rozdrob prstami na menšie kúsky.","Na panvici rozohrej olej, orestuj cibuľu a papriku, kým nezmäknú.","Pridaj rozdrobené tofu, zasyp kurkumou a dobre premiešaj. Opekaj asi 5 minút. Dochuť.","Rozdeľ upečené sladké zemiaky a porciu falošnej tofu praženice."],
tip:"Tofu praženica pri ohrievaní v mikrovlnke nesmrdí po celom office.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv51",n:"Tofu Teriyaki",c:"obed",p:58,s:3,k:420,pr:20,ca:55,f:12,tm:20,
ing:["2 balenia bieleho pevného tofu (spolu cca 360 g)","150 g ryžových rezancov","200 g brokolice","4 PL kvalitnej teriyaki omáčky","1 PL sezamového oleja (alebo olivového)","1 PL sezamových semienok"],
st:["Ryžové rezance zalej vriacou vodou a nechaj zmäknúť (3–5 minút). Sceď a prepláchni studenou vodou.","Brokolicu rozober na malé ružičky a zalej vriacou vodou na 3 minúty.","Tofu osuš, nakrájaj na kocky a opeč na panvici so sezamovým olejom dochrumkava.","K tofu vylej teriyaki omáčku, nechaj minútu skaramelizovať a stiahni z ohňa.","Na dno ulož rezance, na ne brokolicu a lepkavé teriyaki tofu. Posyp sezamom."],
tip:"Rezance po scedení premasíruj pár kvapkami sezamového oleja, aby sa nelepili.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv52",n:"Šošovicový šalát",c:"obed",p:59,s:3,k:390,pr:18,ca:45,f:14,tm:15,
ing:["2 konzervy hnedej alebo zelenej šošovice (spolu cca 480 g po odkvapkaní)","150 g cherry paradajok","1 šalátová uhorka","100 g syra feta (alebo balkánskeho syra)","2 PL olivového oleja, 1 PL citrónovej šťavy","hrsť čerstvej petržlenovej vňate, soľ, mleté čierne korenie"],
st:["Šošovicu z konzervy dôkladne prepláchni a nechaj odkvapkať.","Uhorku nakrájaj na malé kocky a cherry paradajky na polovice. Vňať nasekaj nadrobno.","Vo veľkej miske zmiešaj šošovicu so zeleninou.","Zalej zálievkou z olivového oleja, citrónovej šťavy, soli a korenia.","Šalát rozdeľ do nádob a navrch rozdrob feta."],
tip:"Nepotrebuješ mikrovlnku, stačí otvoriť a jesť. Citrón pomáha vstrebávať železo.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv53",n:"Fazuľové fašírky",c:"obed",p:60,s:3,k:410,pr:18,ca:52,f:10,tm:35,
ing:["2 konzervy červenej fazule (spolu cca 480 g po odkvapkaní)","400 g zemiakov (alebo batátov)","1 vajíčko","50 g jemných ovsených vločiek","1 ČL sušeného cesnaku, 1 ČL mletej papriky, soľ, korenie","1 PL olivového oleja"],
st:["Zemiaky nakrájaj na mesiačiky, pokvapkaj olejom, osoľ a daj piecť na plech (200 °C na 25 minút).","Fazuľu prepláchni, osuš a v miske roztlač vidličkou na hrubú kašu.","K fazuli pridaj vajíčko, ovsené vločky a koreniny. Dobre vypracuj hmotu.","Vlhkými rukami vytvaruj 6 fašírok a ulož ich na plech k zemiakom asi 15 minút pred koncom pečenia.","Do každej nádoby daj upečené zemiaky a 2 fazuľové fašírky."],
tip:"Pečením v rúre predídeš tomu, aby z fašírok v mikrovlnke vytiekla mastná mláka.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv54",n:"Hrachová kaša",c:"obed",p:61,s:3,k:430,pr:24,ca:55,f:11,tm:30,
ing:["250 g žltého poleného hrachu (sušeného)","180 g údeného tofu (1 balenie)","1 stredná cibuľa","2 strúčiky cesnaku","1 PL oleja","1 PL majoránky, soľ, mleté čierne korenie"],
st:["Žltý polený hrach prepláchni a daj variť do osolenej vody (pomer 1:2) na miernom ohni asi 25 minút.","Na panvici rozohrej olej. Cibuľu nakrájaj na pásiky a údené tofu na malé kocky. Opekaj ich, kým tofu neschrumkavie.","Keď je hrach mäkký, pridaj k nemu pretlačený cesnak a majoránku. Dobre rozmiešaj.","Hrachovú kašu rozdeľ a vrch bohato posyp opečenou cibuľkou a údeným tofu."],
tip:"Pred zohrievaním kašu pokvapkaj lyžicou vody, aby opäť získala krémovosť.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv55",n:"Cícerová panvica",c:"obed",p:62,s:3,k:400,pr:15,ca:50,f:12,tm:20,
ing:["2 konzervy cíceru (spolu cca 480 g po odkvapkaní)","150 g quinoy (v suchom stave)","1 stredná cuketa","1 červená paprika","200 ml pasírovaných paradajok (passata)","1 PL olivového oleja, oregáno, soľ, korenie"],
st:["Quinou prepláchni horúcou vodou a uvar (cca 15 minút).","Cuketu a papriku nakrájaj na menšie kocky. Na panvici rozohrej olej a zeleninu opekaj asi 5 minút.","Pridaj prepláchnutý cícer, zalej pasírovanými paradajkami a pridaj oregáno, soľ a korenie.","Nechaj prebublávať 5–7 minút.","Do jednej časti ulož quinou a do druhej cícerovo-zeleninovú zmes."],
tip:"Quinoa nenasáva vlhkosť tak agresívne ako ryža a cícer drží štruktúru aj na 4. deň.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv56",n:"Tofu Kung Pao",c:"obed",p:63,s:3,k:430,pr:20,ca:52,f:14,tm:25,
ing:["2 balenia pevného tofu (spolu cca 360 g)","150 g ryže (basmati)","1 veľká červená paprika","40 g nesolených arašidov","3 PL sójovej omáčky, 1 PL medu, 1 PL octu (alebo limetkovej šťavy)","1 ČL čili vločiek, 1 PL oleja"],
st:["Ryžu uvar klasicky v osolenej vode.","Tofu osuš a nakrájaj na kocky. Papriku nakrájaj na menšie kúsky.","Na panvici rozohrej olej a tofu opekaj dochrumkava (cca 8 minút). Pridaj papriku a arašidy, opekaj ďalšie 3 minúty.","V miske zmiešaj sójovú omáčku, med, ocot a čili. Vylej na panvicu a nechaj 1–2 minúty zredukovať.","Do jednej polovice ulož ryžu, do druhej lepkavé Kung Pao s arašidmi."],
tip:"Lepkavá omáčka funguje ako konzervant a zabráni vysušeniu tofu v mikrovlnke.",t:["mealprep","mikrovlnka","pikantne","bezmasa"]},
{id:"kbv57",n:"Cícer na paprike",c:"obed",p:64,s:3,k:410,pr:18,ca:50,f:11,tm:20,
ing:["2 konzervy cíceru (spolu cca 480 g po odkvapkaní)","180 g celozrnných cestovín (napr. kolienka alebo fusilli)","1 stredná cibuľa","2 PL mletej sladkej papriky","100 ml smotany na varenie (10 %)","1 PL oleja, soľ"],
st:["Cestoviny uvar v osolenej vode domäkka.","Cibuľu nakrájaj nadrobno a orestuj na oleji.","Stiahni oheň, zasyp cibuľu sladkou paprikou, rýchlo premiešaj a ihneď podlej 150 ml vody.","Pridaj prepláchnutý cícer, osoľ a nechaj dusiť 10 minút.","Na záver vlej smotanu a nechaj prebublať.","Rozdeľ cestoviny a zalej ich cícerovo-paprikovou omáčkou."],
tip:"Omáčka v chladničke mierne zhustne, preto pred ohrievaním pridaj lyžicu vody.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv58",n:"Arašidové tofu",c:"obed",p:65,s:3,k:440,pr:22,ca:48,f:16,tm:25,
ing:["2 balenia bieleho pevného tofu (spolu cca 360 g)","150 g ryže (basmati)","200 g zelených fazuliek (čerstvých alebo mrazených)","2 PL 100 % arašidového masla","1 PL sójovej omáčky, 1 PL javorového sirupu (alebo medu)","kvapka horúcej vody, 1 PL oleja"],
st:["Ryžu uvar klasicky. Zelené fazuľky uvar v pare domäkka.","V malej miske vymiešaj arašidové maslo, sójovku, sirup a trochu horúcej vody.","Tofu rozdrob rukami alebo nakrájaj na kocky a opeč na panvici s olejom dozlatista.","Zalej arašidovou omáčkou a dobre premiešaj.","Do krabičiek ulož ryžu, vedľa zelené fazuľky a navrch arašidové tofu."],
tip:"Arašidová omáčka je mimoriadne stabilná a udrží tofu šťavnaté aj na tretí deň.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv59",n:"Fazuľové ragú",c:"obed",p:66,s:3,k:420,pr:17,ca:58,f:9,tm:20,
ing:["2 konzervy bielej fazule (spolu cca 480 g po odkvapkaní)","180 g cestovín penne alebo fusilli","300 ml pasírovaných paradajok (passata)","1 stredná mrkva (nastrúhaná najemno)","1 strúčik cesnaku, talianske bylinky","1 PL olivového oleja, soľ"],
st:["Cestoviny uvar v osolenej vode domäkka a sceď.","Na panvici rozohrej olej a jemne orestuj nastrúhanú mrkvu s pretlačeným cesnakom.","Pridaj prepláchnutú bielu fazuľu, zalej passatou, osoľ a pridaj bylinky.","Dus na miernom ohni zhruba 10 minút, kým omáčka nezhustne.","Vmiešaj uvarené cestoviny priamo do horúceho ragú."],
tip:"Biela fazuľa sa jemne rozpadne a vytvorí dokonalú hustú konzistenciu.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv60",n:"Fazuľa na kyslo",c:"obed",p:67,s:3,k:380,pr:16,ca:55,f:8,tm:25,
ing:["2 konzervy bielej alebo strakatej fazule (spolu cca 480 g po odkvapkaní)","400 g zemiakov","3 vajíčka (uvarené natvrdo)","100 ml smotany na varenie (10 %)","1 bobkový list, 1 PL octu","soľ a mleté čierne korenie"],
st:["Zemiaky ošúp, nakrájaj na menšie kocky a daj variť do menšieho množstva osolenej vody spolu s bobkovým listom (vodu nezlievaj).","K mäkkým zemiakom pridaj prepláchnutú fazuľu.","Vlej smotanu a nechaj prebublať 3 minúty, kým sa vytvorí hustejšia omáčka.","Odstav z ohňa, vyber bobkový list a dochuť lyžicou octu a čiernym korením.","Rozdeľ prívarok a na vrch každej krabičky polož prekrojené vajíčko."],
tip:"Prívarok v chladničke stuhne, takže si zachová dokonalú textúru.",t:["mealprep","mikrovlnka","bezmasa"]},

{id:"kbv61",n:"Kurací wrap",c:"obed",p:69,s:3,k:420,pr:35,ca:45,f:10,tm:15,
ing:["3 ks veľkých celozrnných tortíll","350 g kuracích pŕs","150 g bieleho gréckeho jogurtu","1 PL plnotučnej horčice","1/2 šalátovej uhorky, 1 červená paprika","2 hrste ľadového šalátu (alebo rímskeho)","1 PL oleja, soľ, obľúbené korenie na kura"],
st:["Kuracie prsia nakrájaj na menšie kúsky, osoľ, okoreň a opeč na panvici s olejom dozlatista. Nechaj mierne vychladnúť.","V malej miske zmiešaj grécky jogurt s horčicou, štipkou soli a korenia.","Uhorku a papriku nakrájaj na tenké pásiky.","Každú tortillu potri dresingom. Do stredu ulož listy šalátu, zeleninu a opečené kura. Pevne zabaľ.","Každý wrap prekroj na polovicu a ulož do krabičky."],
tip:"Ulož ako prvú vrstvu na dresing vždy list šalátu – funguje ako izolačná vrstva.",t:["mealprep","rychle","studene"]},
{id:"kbv62",n:"Tuniakový wrap",c:"obed",p:70,s:3,k:450,pr:32,ca:42,f:15,tm:10,
ing:["3 ks veľkých celozrnných tortíll","2 konzervy tuniaka vo vlastnej šťave (spolu cca 240 g)","3 vajíčka (uvarené natvrdo)","100 g bieleho gréckeho jogurtu","50 g kukurice (z konzervy)","2 hrste čerstvého baby špenátu","soľ, mleté čierne korenie, kvapka citrónovej šťavy"],
st:["Tuniaka dôkladne sceď.","V miske roztlač uvarené vajíčka vidličkou. Pridaj tuniaka, kukuricu, grécky jogurt a citrónovú šťavu. Dochuť.","Na každú tortillu ulož vrstvu baby špenátu a na ňu rozotri tuniakovú zmes.","Tortilly pevne zroluj.","Wrapy prekroj na polovice a nalož do krabičiek."],
tip:"Tento obed môžeš jesť aj jednou rukou pri práci na počítači.",t:["mealprep","rychle","studene"]},
{id:"kbv63",n:"Quinoa šalát",c:"obed",p:71,s:3,k:380,pr:15,ca:45,f:14,tm:10,
ing:["150 g quinoy (v suchom stave)","100 g syra feta (alebo balkánskeho syra)","1 šalátová uhorka","200 g cherry paradajok","1 červená cibuľa","2 PL olivového oleja, šťava z 1/2 citróna","čerstvá petržlenová vňať, soľ, korenie"],
st:["Quinou prepláchni pod horúcou vodou a uvar v dvojnásobnom množstve osolenej vody (cca 15 minút). Nechaj úplne vychladnúť.","Nakrájaj uhorku a cibuľu na malé kocky a cherry paradajky na polovice. Nasekaj vňať.","V miske zmiešaj studenú quinou so zeleninou.","Zalej zálievkou z olivového oleja, citrónovej šťavy, soli a korenia.","Rozdeľ do nádob a navrch rozdrob feta."],
tip:"Quinoa v krabičke nezvädne – čím dlhšie stojí, tým lepšie nasaje dresing.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv64",n:"Hummus wrap",c:"obed",p:72,s:3,k:390,pr:14,ca:48,f:16,tm:10,
ing:["3 ks veľkých celozrnných tortíll","150 g kvalitného hummusu (klasický alebo cviklový)","100 g syra feta (alebo halloumi)","1 väčšia mrkva (nastrúhaná najemno)","1 červená paprika (nakrájaná na prúžky)","2 hrste čerstvého baby špenátu"],
st:["Každú tortillu štedro potri hummusom po celej ploche.","Na hummus rovnomerne rozlož listy baby špenátu.","Do stredu navrstvi nastrúhanú mrkvu a prúžky papriky.","Vrch posyp rozdrobenou fetou.","Tortilly pevne zroluj a prekroj na polovice."],
tip:"Hummus slúži aj ako lepidlo, ktoré drží tortillu pokope.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv65",n:"Orzo šalát",c:"obed",p:73,s:3,k:430,pr:32,ca:45,f:12,tm:20,
ing:["150 g orzo cestovín (alebo slovenskej tarhoni)","300 g kuracích pŕs","1 šalátová uhorka","50 g čiernych olív (bez kôstky)","1 PL olivového oleja","1 ČL sušeného oregána, soľ, mleté čierne korenie, citrónová šťava"],
st:["Orzo cestoviny uvar v osolenej vode domäkka, sceď a prepláchni studenou vodou.","Kuracie prsia nakrájaj na malé kocky, osoľ, okoreň a opeč na panvici. Nechaj vychladnúť.","Uhorku nakrájaj na malé kocky, olivy na kolieska.","Vo veľkej miske zmiešaj studené orzo s mäsom, uhorkou a olivami. Zalej olejom, pridaj oregáno a kvapku citrónu."],
tip:"Orzo stvrdne v chladničke oveľa menej ako ryža a vďaka oleju nevyschne.",t:["mealprep","studene"]},
{id:"kbv66",n:"Kuskus šalát",c:"obed",p:74,s:3,k:410,pr:35,ca:45,f:9,tm:15,
ing:["150 g celozrnného kuskusu (v suchom stave)","350 g kuracích pŕs","1 šalátová uhorka, 1 červená paprika","1 PL olivového oleja","šťava z 1/2 citróna, soľ, mleté čierne korenie"],
st:["Kuskus zalej vriacou vodou, osoľ, prikry a nechaj 5 minút napučať. Prekypri vidličkou a nechaj vychladnúť.","Kuracie prsia nakrájaj na menšie kocky, osoľ, okoreň a opeč na panvici. Nechaj vychladnúť.","Uhorku a papriku nakrájaj na drobné kocky.","Vo veľkej miske zmiešaj kuskus, mäso a zeleninu. Zalej olejom a citrónovou šťavou."],
tip:"Kuskus je na studené šaláty lepší ako ryža, v chladničke nestvrdne.",t:["mealprep","rychle","studene"]},
{id:"kbv67",n:"Vajíčkový wrap",c:"obed",p:75,s:3,k:440,pr:22,ca:45,f:18,tm:15,
ing:["3 ks veľkých celozrnných tortíll","6 vajíčok (uvarených natvrdo)","100 g bieleho gréckeho jogurtu","1 PL plnotučnej horčice","2 hrste čerstvého baby špenátu","soľ, mleté čierne korenie, pažítka"],
st:["Uvarené vajíčka ošúp a v miske ich vidličkou roztlač na menšie kúsky.","Pridaj grécky jogurt, horčicu, nasekanú pažítku, soľ a korenie. Premiešaj na hustú pomazánku.","Na každú tortillu ulož vrstvu baby špenátu a naň nanes vajíčkovú zmes.","Pevne zabaľ do tvaru valca.","Wrapy prekroj šikmo na polovice."],
tip:"Grécky jogurt namiesto majonézy zníži kalórie a wrap nepremokne.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv68",n:"Cícerový šalát",c:"obed",p:76,s:3,k:390,pr:18,ca:48,f:12,tm:10,
ing:["2 konzervy cíceru (spolu cca 480 g po odkvapkaní)","150 g cherry paradajok","100 g syra feta","1/2 červenej cibule","1 PL olivového oleja, 1 PL balzamikového octu","hrsť čerstvej petržlenovej vňate, soľ, korenie"],
st:["Cícer dôkladne prepláchni v sitku pod studenou vodou a nechaj odkvapkať.","Cherry paradajky prekroj na polovice, červenú cibuľu nakrájaj na tenké polmesiačiky.","V miske zmiešaj cícer, paradajky, cibuľu a nasekanú petržlenovú vňať.","Zalej olivovým olejom a balzamikovým octom. Dochuť korením.","Šalát rozdeľ do nádob a navrch rozmrv feta."],
tip:"Cícer je najstabilnejšia strukovina na studené šaláty – vydrží v chladničke aj 4 dni.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv69",n:"Arašidové rezance",c:"obed",p:77,s:3,k:450,pr:24,ca:52,f:15,tm:20,
ing:["150 g soba rezancov (pohánkové) alebo celozrnných špagiet","200 g údeného tofu","1 mrkva, 1 červená paprika","2 PL 100 % arašidového masla","1 PL sójovej omáčky, šťava z 1/2 limetky, trochu teplej vody"],
st:["Rezance uvar domäkka, sceď a poriadne prepláchni ľadovou vodou.","Mrkvu a papriku nakrájaj na tenké zápalky (julienne). Údené tofu nakrájaj na malé kocky.","V malej miske vymiešaj arašidové maslo, sójovú omáčku, limetkovú šťavu a 2–3 lyžice teplej vody.","Vo veľkej miske zmiešaj studené rezance, surovú zeleninu a tofu. Prelej dresingom."],
tip:"Arašidový dresing v chladničke mierne stuhne a krásne obalí rezance.",t:["mealprep","studene","bezmasa"]},
{id:"kbv70",n:"Morčací wrap",c:"obed",p:78,s:3,k:410,pr:25,ca:43,f:14,tm:10,
ing:["3 ks veľkých celozrnných tortíll","200 g kvalitnej morčacej šunky (v plátkoch)","100 g krémového syra (typu Lučina / Philadelphia light)","1 stredná mrkva (nastrúhaná najemno)","2 hrste čerstvej rukoly"],
st:["Každú tortillu rovnomerne potri krémovým syrom.","Na syr ulož plátky morčacej šunky.","Do stredu navrstvi nastrúhanú mrkvu a pridaj čerstvú rukolu.","Tortilly natesno zroluj a prekroj na polovice.","Ulož nakrájané wrapy do krabičiek tesne vedľa seba."],
tip:"Krémový syr slúži ako izolačná vrstva, vďaka ktorej tortilla nezvlhne.",t:["mealprep","rychle","studene"]},
{id:"kbv71",n:"Batátový šalát",c:"obed",p:79,s:3,k:400,pr:15,ca:46,f:16,tm:30,
ing:["400 g batátov (sladkých zemiakov)","150 g balkánskeho syra (alebo fety)","2 hrste čerstvého baby špenátu","30 g vlašských orechov (nasekaných)","1 PL olivového oleja, štipka sušeného tymianu, soľ"],
st:["Batáty ošúp, nakrájaj na menšie kocky, pokvapkaj olivovým olejom, osoľ, posyp tymianom a daj piecť na 200 °C asi 20 minút. Nechaj úplne vychladnúť.","Do veľkej misky vlož čerstvý baby špenát.","Pridaj studené upečené batáty, nasekané vlašské orechy a dobre premiešaj.","Rozdeľ šalát a navrch rozdrob balkánsky syr."],
tip:"Tento šalát nepotrebuje žiadny tekutý dresing – batáty sú po upečení dosť šťavnaté.",t:["mealprep","studene","bezmasa"]},
{id:"kbv72",n:"Lososový wrap",c:"obed",p:80,s:3,k:460,pr:25,ca:44,f:18,tm:10,
ing:["3 ks veľkých celozrnných tortíll","150 g údeného lososa (v plátkoch)","100 g krémového syra (typu Lučina)","1 menšie zrelé avokádo","2 hrste obľúbeného listového šalátu","šťava z 1/2 citróna, mleté čierne korenie"],
st:["Avokádo nakrájaj na tenké plátky a okamžite ho bohato pokvapkaj citrónovou šťavou.","Tortilly natri krémovým syrom a zľahka posyp čiernym korením.","Na syr ulož plátky údeného lososa, plátky avokáda a čerstvý šalát.","Tortilly pevne zroluj a prekroj na polovice."],
tip:"Citrónová šťava je kriticky dôležitá – avokádo ostane zelené aj na tretí deň.",t:["mealprep","rychle","studene"]},
{id:"kbv73",n:"Mexický šalát",c:"obed",p:81,s:3,k:420,pr:30,ca:50,f:10,tm:15,
ing:["300 g kuracích pŕs","1 konzerva červenej fazule (240 g po odkvapkaní)","150 g kukurice (z konzervy)","1 červená paprika","1 PL olivového oleja, šťava z 1 limetky","1 ČL taco/mexického korenia, soľ"],
st:["Kuracie prsia nakrájaj na drobné kúsky, osoľ, posyp taco korením a opeč na panvici s trochou oleja. Nechaj vychladnúť.","Fazuľu a kukuricu prepláchni studenou vodou. Papriku nakrájaj na kocky.","Vo veľkej miske zmiešaj studené kuracie mäso so strukovinami a paprikou.","Zalej olivovým olejom a limetkovou šťavou."],
tip:"Proteínová bomba, ktorá nepotrebuje žiadnu prílohu.",t:["mealprep","rychle","studene","pikantne"]},
{id:"kbv74",n:"Pohánkový šalát",c:"obed",p:82,s:3,k:420,pr:20,ca:45,f:16,tm:15,
ing:["150 g pohánky (v suchom stave)","2 balenia bieleho pevného tofu (spolu cca 360 g)","1 veľká predvarená cvikla (vákuovo balená)","1 PL balzamikového octu, 1 PL olivového oleja","hrsť vlašských orechov (nasekaných)","soľ, čierne korenie"],
st:["Pohánku prepláchni vriacou vodou a uvar do mäkka (cca 15 minút). Nechaj vychladnúť.","Tofu osuš, nakrájaj na kocky, zľahka osoľ a opeč na panvici dochrumkava.","Predvarenú cviklu nakrájaj na malé kocky.","V miske zmiešaj studenú pohánku, opečené tofu, cviklu a nasekané orechy. Zalej olejom a balzamikom."],
tip:"Pohánka z cvikly nasaje krásnu ružovú farbu.",t:["mealprep","studene","bezmasa"]},
{id:"kbv75",n:"Caprese wrap",c:"obed",p:83,s:3,k:430,pr:22,ca:45,f:16,tm:15,
ing:["3 ks veľkých celozrnných tortíll","2 balenia mozzarelly light (spolu cca 200 g)","2 veľké mäsité paradajky","3 PL kvalitného bazalkového pesta","2 hrste čerstvej rukoly"],
st:["Mozzarellu a paradajky nakrájaj na tenšie plátky.","Každú tortillu natri lyžicou bazalkového pesta.","Do stredu ulož vrstvu rukoly. Na ňu striedavo poukladaj plátky paradajky a mozzarelly.","Tortilly pevne zroluj a prekroj šikmo na polovice."],
tip:"Prvá vrstva pesta a rukoly vytvorí ochranu a wrap sa v chladničke nerozmočí.",t:["mealprep","rychle","studene","bezmasa"]},

{id:"kbv76",n:"Hovädzie Udon",c:"obed",p:85,s:3,k:440,pr:28,ca:55,f:12,tm:20,
ing:["300 g chudého hovädzieho mäsa (falošná sviečková, na tenké pásiky)","200 g Udon rezancov (v suchom stave, alebo 450 g predvarených)","1 červená paprika, 150 g cukrového hrášku (lúskov)","3 PL sójovej omáčky, 1 PL ustricovej omáčky","1 ČL sezamového oleja, 1 strúčik cesnaku, kúsok čerstvého zázvoru"],
st:["Udon rezance uvar podľa návodu a sceď.","Na wok panvici rozohrej olej, pridaj pretlačený cesnak a nastrúhaný zázvor. Hneď pridaj hovädzie mäso a sprudka ho opekaj 3–4 minúty.","Pridaj nakrájanú papriku a cukrový hrášok. Opekaj ďalšie 3 minúty.","Do panvice vhoď uvarené Udon rezance, zalej sójovou a ustricovou omáčkou a zakvapkaj sezamovým olejom. Premiešaj na silnom ohni."],
tip:"Hrubé Udon rezance sa v mikrovlnke nerozvaria na kašu.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv77",n:"Kuracie Pad Thai",c:"obed",p:86,s:3,k:450,pr:35,ca:50,f:12,tm:25,
ing:["350 g kuracích pŕs","150 g ryžových rezancov (plochých)","2 vajíčka","100 g mungo klíčkov (voliteľné)","3 PL sójovej omáčky, 1 PL medu, šťava z 1 limetky","30 g nesolených arašidov (nasekaných)"],
st:["Ryžové rezance zalej vriacou vodou a nechaj zmäknúť. Sceď ich.","V miske zmiešaj sójovku, med a limetkovú šťavu.","Kuracie prsia nakrájaj na malé kocky a opeč na panvici dozlatista. Mäso odhrň na okraj, rozbi tam vajíčka a rýchlo ich rozmiešaj.","Pridaj zmäknuté ryžové rezance a pripravenú omáčku. Rýchlo zmiešaj. Pridaj mungo klíčky a odstav.","Rozdeľ do krabičiek a vrch posyp nasekanými arašidmi."],
tip:"Pribaľ si mesiačik čerstvej limetky a pokvapkaj až v práci po zohriatí.",t:["mealprep","mikrovlnka"]},
{id:"kbv78",n:"Ázijské bravčové",c:"obed",p:87,s:3,k:460,pr:32,ca:50,f:14,tm:25,
ing:["350 g chudého bravčového mäsa (karé alebo panenka)","150 g ryže (basmati)","200 g zelených fazuliek","1 PL omáčky Hoisin","2 PL sójovej omáčky, 1 strúčik cesnaku","1 PL oleja, štipka čili"],
st:["Ryžu uvar klasicky v osolenej vode. Zelené fazuľky uvar v pare domäkka.","Bravčové mäso nakrájaj na úplne tenké rezančeky.","Na panvici rozohrej olej, pridaj pretlačený cesnak a bravčové mäso. Sprudka opekaj.","Zalej sójovou omáčkou a Hoisin, pridaj čili. Omáčka obalí mäso lesklou vrstvou.","K mäsu vhoď zelené fazuľky a prehrej ich v omáčke 1 minútu.","Na dno ulož ryžu a na ňu bravčové rezančeky."],
tip:"Hoisin omáčka funguje ako ázijské BBQ – po ohriatí je chuť intenzívna.",t:["mealprep","mikrovlnka","pikantne"]},
{id:"kbv79",n:"Zelené kari",c:"obed",p:88,s:3,k:420,pr:32,ca:45,f:12,tm:20,
ing:["350 g kuracích pŕs","150 g jazmínovej ryže","200 ml kokosového mlieka (light)","1 PL zelenej kari pasty","1 menšia cuketa, 1 hrsť baby špenátu","1 PL oleja, kvapka limetkovej šťavy"],
st:["Ryžu uvar klasicky vo vode. Cuketu nakrájaj na menšie kocky.","Na hlbšej panvici orestuj na oleji zelenú kari pastu (asi 30 sekúnd).","Pridaj na kocky nakrájané kuracie mäso a opeč ho do zatiahnutia.","Pridaj cuketu a všetko zalej kokosovým mliekom. Nechaj prebublávať asi 10 minút.","Mimo ohňa vhoď baby špenát, zakvapkaj limetkou a premiešaj."],
tip:"Kokosové mlieko si výborne udržiava krémovú štruktúru aj pri nízkych teplotách.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv80",n:"Sladkokyslé krevety",c:"obed",p:89,s:3,k:380,pr:22,ca:55,f:6,tm:15,
ing:["300 g kreviet (očistených, predvarených alebo surových)","150 g ryže","1 červená paprika, 150 g ananásu (čerstvý alebo z konzervy)","2 PL pasírovaných paradajok (alebo kečupu)","1 PL sójovej omáčky, 1 PL medu, 1 PL jablčného octu","1 PL oleja"],
st:["Ryžu uvar klasicky vo vode.","Papriku a ananás nakrájaj na kocky.","V miske zmiešaj paradajky, sójovku, med a ocot na sladkokyslú omáčku.","Na panvici rozohrej olej a orestuj papriku s ananásom (asi 3 minúty).","Pridaj krevety a omáčku. Opekaj spolu ďalšie 3 minúty.","Do každej nádoby daj porciu ryže a navrch sladkokyslú krevetovú zmes."],
tip:"Ohrievaj na strednom výkone a kratšie, aby krevety nestvrdli.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv81",n:"Pomarančové kura",c:"obed",p:90,s:3,k:430,pr:36,ca:48,f:9,tm:25,
ing:["350 g kuracích pŕs","150 g jazmínovej ryže","1 červená paprika","1 veľký, šťavnatý pomaranč (šťava a kôra z polovice)","2 PL sójovej omáčky, 1 PL medu","1 ČL kukuričného škrobu, 1 PL oleja"],
st:["Ryžu uvar vo vode. Papriku nakrájaj na menšie kocky.","V miske rozmiešaj šťavu z celého pomaranča, nastrúhanú kôru, sójovú omáčku, med a kukuričný škrob.","Kuracie prsia nakrájaj na kocky a orestuj na panvici s olejom. Keď sú prepečené, pridaj papriku a opekaj 2 minúty.","Zalej pomarančovou omáčkou. Zmes vďaka škrobu zhustne a získa lesk.","Do jednej polovice nádoby ulož ryžu, do druhej pomarančové kura."],
tip:"Kukuričný škrob zabráni tomu, aby omáčka stiekla na dno a rozmočila ryžu.",t:["mealprep","mikrovlnka"]},
{id:"kbv82",n:"Kórejské hovädzie",c:"obed",p:91,s:3,k:450,pr:30,ca:48,f:14,tm:15,
ing:["350 g chudého mletého hovädzieho mäsa","150 g ryže (basmati)","1 šalátová uhorka","3 PL sójovej omáčky","1 PL sezamového oleja, 1 PL medu (alebo hnedého cukru)","1 strúčik cesnaku, kúsok čerstvého zázvoru, sezam"],
st:["Ryžu uvar klasicky vo vode. Uhorku nakrájaj na úplne tenké plátky.","Na rozpálenej panvici nasucho opeč mleté hovädzie mäso a rozbíjaj ho vareškou.","Keď je mäso prepečené, pridaj pretlačený cesnak a nastrúhaný zázvor.","Vlej sójovú omáčku, sezamový olej a med. Opekaj 2–3 minúty, kým mäso neskaramelizuje.","Nalož ryžu, vedľa surové plátky uhorky a na ryžu kórejské mäso. Posyp sezamom."],
tip:"Pred ohrevom si uhorku vyber – slúži ako chrumkavý kontrast.",t:["mealprep","mikrovlnka","rychle"]},
{id:"kbv83",n:"Mango kari",c:"obed",p:92,s:3,k:440,pr:33,ca:50,f:11,tm:25,
ing:["350 g kuracích pŕs","150 g ryže (jazmínovej)","1 zrelé sladké mango","150 ml kokosového mlieka (light)","1 PL žltej kari pasty","1 PL oleja, hrsť čerstvého koriandra"],
st:["Ryžu uvar podľa návodu.","Mango ošúp. Polovicu rozmixuj na hladké pyré, druhú nakrájaj na kocky.","Kuracie mäso nakrájaj na menšie kocky. Na panvici zohrej olej, orestuj kari pastu a pridaj mäso. Sprudka opeč.","Zalej mäso kokosovým mliekom a mangovým pyré. Nechaj 10 minút prevrieť.","Po odstavení vmiešaj kocky manga a nasekaný koriander."],
tip:"Mango sa s pikantnou kari pastou po 24 hodinách v chladničke dokonale prepojí.",t:["mealprep","mikrovlnka","pikantne"]},
{id:"kbv84",n:"Teriyaki losos",c:"obed",p:93,s:3,k:460,pr:28,ca:45,f:18,tm:25,
ing:["3 porcie čerstvého lososa (cca 120 g každý kúsok bez kože)","150 g ryže (basmati)","250 g brokolice","3 PL kvalitnej teriyaki omáčky","1 ČL sezamového oleja","sezamové semienka"],
st:["Ryžu uvar. Brokolicu rozober na malé ružičky a var v pare alebo vo vriacej vode 4 minúty.","Lososa nakrájaj na väčšie kocky.","Na panvici zohrej sezamový olej a kocky lososa sprudka opekaj zhruba 2 minúty z každej strany.","Zalej rybu teriyaki omáčkou a panvicou len jemne potras. Nechaj minútu karamelizovať.","Na dno ulož ryžu a brokolicu, navrch kocky teriyaki lososa a posyp sezamom."],
tip:"V práci nastav mikrovlnku na polovičný výkon a ohrievaj maximálne minútu a pol.",t:["mealprep","mikrovlnka"]},
{id:"kbv85",n:"Sladké čili kura",c:"obed",p:94,s:3,k:410,pr:35,ca:48,f:7,tm:20,
ing:["350 g kuracích pŕs","150 g jazmínovej ryže","200 g cukrového hrášku (lúsky) alebo mrazenej zelenej fazuľky","3 PL omáčky Sweet Chili","1 PL sójovej omáčky","1 PL oleja"],
st:["Ryžu uvar. Cukrový hrášok prepláchni vodou.","Mäso nakrájaj na malé kocky a na rozpálenom oleji ho sprudka opeč.","Keď je kura zlatisté, vhoď cukrový hrášok a opekaj ďalšie 2 minúty.","Vylej do panvice sladkú čili omáčku zmiešanú so sójovou. Prebublať minútku.","Naber ryžu, na ktorú položíš mäso s hráškom."],
tip:"Cukrový hrášok ti v práci krásne schrumká aj po ohriatí.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv86",n:"Červené kari",c:"obed",p:95,s:3,k:440,pr:36,ca:46,f:12,tm:25,
ing:["350 g morčacích pŕs","150 g ryže (basmati)","200 ml kokosového mlieka (light)","1 PL červenej kari pasty","1 červená paprika, 100 g bambusových výhonkov (z konzervy)","1 PL oleja, kvapka rybej alebo sójovej omáčky"],
st:["Ryžu uvar v osolenej vode.","Morčacie mäso nakrájaj na kocky, papriku na tenké pásiky a bambusové výhonky prepláchni.","Na hlbšej panvici orestuj červenú kari pastu na oleji. Pridaj mäso a sprudka ho opeč.","Pridaj papriku a bambusové výhonky, zalej kokosovým mliekom a dochuť kvapkou rybej omáčky.","Dus na miernom ohni asi 10 minút."],
tip:"Morčacie mäso po ohriatí v kokosovom mlieku neostane suché.",t:["mealprep","mikrovlnka","pikantne"]},
{id:"kbv87",n:"Thajské bazalkové kura",c:"obed",p:96,s:3,k:410,pr:35,ca:46,f:9,tm:15,
ing:["350 g mletého kuracieho mäsa","150 g jazmínovej ryže","150 g zelenej fazuľky","2 hrste čerstvej bazalky (ideálne thajskej)","2 PL sójovej omáčky, 1 ČL medu","2 strúčiky cesnaku, 1 PL oleja, štipka čili"],
st:["Ryžu uvar klasicky vo vode.","Na panvici zohrej olej, pridaj pretlačený cesnak a čili. Hneď vhoď mleté kuracie mäso a rozbíjaj ho vareškou.","Keď je mäso prepečené, pridaj zelené fazuľky, sójovú omáčku a med. Restuj 3 minúty na silnom ohni.","Odstav z ohňa, vhoď čerstvú bazalku a premiešaj.","Rozdeľ ryžu a na ňu navrstvi mleté bazalkové kura."],
tip:"Pad Kra Pao – ak chceš byť profík, pribaľ si do práce volské oko.",t:["mealprep","mikrovlnka","rychle","pikantne"]},
{id:"kbv88",n:"Tuniakové Poke",c:"obed",p:97,s:3,k:430,pr:30,ca:48,f:11,tm:15,
ing:["150 g ryže (ideálne sushi alebo jazmínovej)","2 konzervy tuniaka vo vlastnej šťave (spolu cca 240 g po odkvapkaní)","150 g edamame (zelených sójových bôbov – mrazené)","1/2 uhorky, 1 mrkva","2 PL bieleho jogurtu, 1 ČL Sriracha omáčky","sójová omáčka na pokvapkanie, sezam"],
st:["Ryžu uvar a nechaj ju úplne vychladnúť. Edamame prelej vriacou vodou a nechaj rozmraziť.","Tuniaka poriadne sceď. V malej miske zmiešaj jogurt so Srirachou a zmiešaj to s tuniakom.","Uhorku nakrájaj na tenké plátky, mrkvu nastrúhaj na rezančeky.","Do nádoby ulož studenú ryžu. Na ryžu ulož do samostatných sekcií pikantného tuniaka, edamame, uhorku a mrkvu. Pokvapkaj sójovou omáčkou a posyp sezamom."],
tip:"Záchrana, keď nemáš mikrovlnku. Konzervovaný tuniak vydrží bezpečne 3 dni.",t:["mealprep","rychle","studene","pikantne"]},
{id:"kbv89",n:"Batátové kari",c:"obed",p:98,s:3,k:390,pr:14,ca:55,f:12,tm:30,
ing:["400 g batátov (sladkých zemiakov)","1 konzerva cíceru (240 g po odkvapkaní)","200 ml kokosového mlieka (light)","1 PL žltej kari pasty (alebo 1 PL kari korenia)","2 hrste baby špenátu","150 g ryže","1 PL oleja, soľ"],
st:["Ryžu uvar klasicky. Batáty ošúp a nakrájaj na menšie kocky.","Na hlbšej panvici orestuj na oleji kari pastu.","Pridaj nakrájané batáty a prepláchnutý cícer. Zalej kokosovým mliekom a trochou vody. Osoľ.","Dus pod pokrievkou asi 15–20 minút, kým batáty nezmäknú.","Odstav, vhoď špenát a premiešaj."],
tip:"Sladké zemiaky v kari omáčke sa v mikrovlnke nesprávajú ako špongia.",t:["mealprep","mikrovlnka","pikantne","bezmasa"]},
{id:"kbv90",n:"Pražená ryža",c:"obed",p:99,s:3,k:420,pr:25,ca:50,f:12,tm:15,
ing:["350 g uvarenej ryže (úplne vychladnutej z predošlého dňa)","3 vajíčka","150 g chudej šunky (alebo údeného tofu)","150 g mrazenej zmesi (hrášok, mrkva, kukurica)","3 PL sójovej omáčky","1 ČL sezamového oleja, 1 PL klasického oleja, jarná cibuľka"],
st:["Staršiu uvarenú ryžu rozdrv vidličkou. Mrazenú zeleninu prelej horúcou vodou. Šunku nakrájaj na kocky.","Na veľkej panvici rozohrej olej. Nalej naň rozšľahané vajíčka a urob rýchlu praženicu. Zhrň ich na bok.","Pridaj do panvice ryžu, zeleninu a šunku. Opekaj na prudkom ohni 3–4 minúty.","Zalej sójovou omáčkou a sezamovým olejom. Opekaj ďalšie 2 minúty.","Rozdeľ a posyp nasekanou jarnou cibuľkou."],
tip:"Na praženú ryžu NIKDY nepoužívaj čerstvo uvarenú, teplú ryžu.",t:["mealprep","mikrovlnka","rychle"]},

{id:"kbv91",n:"Tvarohové lievance",c:"dezert",p:101,s:3,k:420,pr:25,ca:45,f:12,tm:25,
ing:["250 g jemného tvarohu","2 vajíčka","100 g ovsených vločiek (zomletých na múku)","1 PL medu, 1/2 ČL kypriaceho prášku","150 g drobného ovocia (čučoriedky/maliny)","1 PL kokosového oleja"],
st:["V miske poriadne rozmiešaj tvaroh s vajíčkami a medom.","Pridaj ovsenú múku s kypriacim práškom a vypracuj hustejšie cesto.","Na panvici rozohrej trochu oleja a lyžicou tvaruj malé lievance. Opekaj z oboch strán dozlatista (cca 2 minúty z každej strany).","Do každej nádoby ulož komínček lievancov a vedľa nich nasyp čerstvé drobné ovocie."],
tip:"Lievance zatváraj do krabičky až keď sú úplne studené.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv92",n:"Zapekaná ovsená kaša",c:"dezert",p:102,s:3,k:390,pr:18,ca:50,f:10,tm:35,
ing:["150 g jemných ovsených vločiek","300 ml polotučného mlieka","2 jablká (nastrúhané nahrubo)","2 vajíčka","1 PL medu, 1 ČL škorice","30 g vlašských orechov (nasekaných)"],
st:["Vo väčšej miske zmiešaj suché vločky so škoricou.","V inej nádobe vyšľahaj mlieko, vajíčka a med. Vylej to na vločky.","Pridaj nastrúhané jablká a všetko dôkladne premiešaj.","Zmes prelej do menšej zapekacej misky a vrch posyp nasekanými orechmi. Peč pri 190 °C asi 25–30 minút.","Upečenú hmotu nakrájaj na 3 veľké štvorce."],
tip:"Zapekaná kaša drží tvar a v krabičke sa neroztečie. Skvelá teplá aj studená.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv93",n:"Ryžový nákyp",c:"dezert",p:103,s:3,k:410,pr:20,ca:60,f:8,tm:45,
ing:["150 g ryže (najlepšie guľatozrnnej)","300 ml mlieka","250 g hrudkovitého tvarohu","2 vajíčka (bielky a žĺtky oddelene)","2 PL medu alebo čakankového sirupu","150 g mrazených čerešní alebo marhúľ"],
st:["Ryžu uvar domäkka v mlieku (za stáleho miešania). Nechaj mierne vychladnúť.","V miske zmiešaj tvaroh, žĺtky a med. V druhej miske vyšľahaj bielky na tuhý sneh.","K uvarenej ryži primiešaj tvarohovú hmotu, mrazené ovocie a nakoniec zľahka sneh z bielkov.","Hmotu prelož do zapekacej misy a peč pri 180 °C približne 30 minút.","Nákyp nechaj vychladnúť, nakrájaj na tretiny a ulož do nádob."],
tip:"Pri ohrievaní nastav stredný výkon mikrovlnky, aby tvaroh nezhorkol.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv94",n:"Sladký kuskus",c:"dezert",p:104,s:3,k:380,pr:15,ca:55,f:10,tm:10,
ing:["150 g celozrnného kuskusu (v suchom stave)","150 ml horúceho mlieka","150 g bieleho gréckeho jogurtu","2 PL medu","1 zrelý banán, 30 g mandlí (plátky)","1 ČL škorice"],
st:["Kuskus nasyp do misky, pridaj škoricu a zalej horúcim mliekom. Prikry a nechaj 5 minút napučať.","Kuskus prekypri vidličkou a vmiešaj lyžicu medu. Nechaj vychladnúť.","Banán nakrájaj na kolieska a grécky jogurt zmiešaj so zvyšnou lyžicou medu.","Na dno krabičky ulož škoricový kuskus. Navrch vrstvu sladkého jogurtu, kolieska banánu a posyp mandľami."],
tip:"Aby banán nezhnedol, pokvapkaj ho troškou citrónovej šťavy.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv95",n:"Ovocné knedličky",c:"dezert",p:105,s:3,k:430,pr:24,ca:52,f:9,tm:20,
ing:["250 g jemného odtučneného tvarohu","1 vajíčko","100 g detskej krupice (alebo pomletých ovsených vločiek)","150 g jahôd (čerstvých alebo mrazených)","3 PL mletého maku, 1 PL masla, 1 PL medu"],
st:["V miske rukou vypracuj z tvarohu, vajíčka a krupice mierne lepivé cesto. Nechaj ho 5 minút odpočívať.","Mokrými rukami odoberaj kúsky cesta, roztlač ich na placku, vlož do stredu kúsok jahody a zabaľ do guličky.","Knedličky hádž do vriacej vody. Keď vyplávajú na povrch, sú hotové (cca 4 minúty).","Na panvici rozpusti maslo s medom a horúce knedličky v tom obaľ.","Rozdeľ knedličky a bohato zasyp mletým makom."],
tip:"Zohrievaj ich len jemne a krátko, aby sa ovocie vo vnútri nerozvarilo.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv96",n:"Tvarohové rezance",c:"dezert",p:106,s:3,k:380,pr:22,ca:55,f:8,tm:15,
ing:["200 g celozrnných cestovín (široké rezance alebo fusilli)","250 g hrudkovitého tvarohu (polotučného)","1 PL masla","2 PL medu alebo čakankového sirupu","štipka škorice (alebo hrozienka)"],
st:["Cestoviny uvar v jemne osolenej vode domäkka a sceď.","Ešte do horúcich cestovín v hrnci vmiešaj lyžicu masla.","Pridaj rozdrobený hrudkovitý tvaroh a med. Dobre premiešaj.","Sladké rezance rozdeľ do nádob a vrch bohato posyp škoricou."],
tip:"Pred ohrevom prilej 1–2 lyžice mlieka alebo vody, aby boli vláčne.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv97",n:"Makové šúľance",c:"dezert",p:107,s:3,k:390,pr:14,ca:58,f:11,tm:30,
ing:["400 g zemiakov (uvarených v šupke a vychladnutých)","100 g celozrnnej špaldovej múky","1 vajíčko","40 g mletého maku","2 PL medu alebo javorového sirupu","1 PL roztopeného masla"],
st:["Uvarené zemiaky ošúp a nastrúhaj najemno (alebo pretlač).","Pridaj k nim vajíčko, špaldovú múku a rukami vypracuj hladké cesto.","Z cesta šúľaj malé valčeky a hádž ich do vriacej osolenej vody. Keď vyplávajú, sú hotové. Sceď ich.","Horúce šúľance prelej roztopeným maslom a medom, pridaj mletý mak a premiešaj."],
tip:"Maslo vytvorí film, vďaka ktorému sa šúľance v krabičke nezlepia.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv98",n:"Jablková žemľovka",c:"dezert",p:108,s:3,k:390,pr:20,ca:48,f:12,tm:35,
ing:["4–5 plátkov celozrnného toastového chleba (alebo 2 staršie celozrnné rožky)","250 g jemného tvarohu","2 menšie jablká (nastrúhané nahrubo)","2 vajíčka, 100 ml mlieka","2 PL medu, škorica","30 g vlašských orechov"],
st:["V hlbokom tanieri rozšľahaj vajíčka, mlieko a 1 PL medu.","V menšej miske zmiešaj tvaroh so zvyšnou lyžicou medu.","Plátky chleba namáčaj vo vajíčkovej zmesi a ulož ich na dno menšej zapekacej misy.","Na chlieb natri tvaroh, navrstvi nastrúhané jablká, posyp škoricou a orechmi. Zakry ďalšou vrstvou namočeného chleba. Zvyšnú zmes vylej navrch.","Peč pri 190 °C asi 25 minút dozlatista.","Nechaj vychladnúť, nakrájaj na 3 kusy."],
tip:"Ak máš sklenené krabičky vhodné do rúry, upeč žemľovku priamo v nich.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv99",n:"Cisársky trhanec",c:"dezert",p:109,s:3,k:360,pr:24,ca:42,f:10,tm:20,
ing:["3 vajíčka (bielky a žĺtky oddelene)","120 g špaldovej hladkej múky","200 ml polotučného mlieka","1 odmerka (30 g) vanilkového proteínu","1 PL masla na opekanie","150 g kvalitnej detskej výživy (100% jablkové pyré) bez cukru"],
st:["V miske zmiešaj žĺtky, mlieko, múku a proteín na hladké cestíčko.","Bielky vyšľahaj na tuhý sneh a jemne ich vmiešaj do cesta.","Na veľkej panvici rozohrej maslo a vylej celé cesto.","Opekaj na miernom ohni, kým spodok nie je zlatistý. Potom ju otoč a dvomi vareškami roztrhaj na menšie kúsky. Opekaj dochrumkava.","Trhanec rozdeľ do krabičiek. Jablkové pyré zabaľ do samostatných nádobiek."],
tip:"Jablkové pyré nelej na trhanec už doma – polej si to až v práci pred jedením.",t:["mealprep","mikrovlnka","rychle","bezmasa"]},
{id:"kbv100",n:"Pudingové vločky",c:"dezert",p:110,s:3,k:390,pr:18,ca:60,f:8,tm:10,
ing:["150 g jemných ovsených vločiek","20 g chia semienok","1 balíček (37 g) vanilkového pudingového prášku","300 ml mlieka","150 g bieleho gréckeho jogurtu","2 PL medu, drobné čerstvé ovocie (maliny, jahody)"],
st:["Pudingový prášok uvar v 300 ml mlieka na veľmi hustý puding.","Kým je puding ešte horúci, vmiešaj do neho ovsené vločky, chia semienka a med. Nechaj 10 minút chladnúť.","Do vychladnutej zmesi zľahka primiešaj biely grécky jogurt.","Pudingovú kašu rozdeľ do krabičiek a navrch poukladaj čerstvé ovocie."],
tip:"Netreba nič zohrievať, v práci len otvoríš a vychutnávaš.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv101",n:"Fit Cheesecake",c:"dezert",p:111,s:3,k:380,pr:20,ca:42,f:14,tm:35,
ing:["350 g jemného tvarohu (odtučneného)","100 g bieleho gréckeho jogurtu","2 vajíčka","2 PL medu (alebo javorového sirupu)","90 g celozrnných sušienok (podrvených na prach)","1 PL masla (roztopeného)"],
st:["Podrvené sušienky zmiešaj s roztopeným maslom.","V miske metličkou dohladka vymiešaj tvaroh, grécky jogurt, vajíčka a med.","Ak máš sklenené krabičky vhodné do rúry, rovno na ich dno utlač sušienkový základ a zalej ho tvarohovou zmesou.","Peč na 160 °C asi 25–30 minút, kým okraje nestuhnú a stred sa jemne trasie."],
tip:"Cheesecake je kráľ studených obedov – jesť ho budeš priamo z chladničky.",t:["mealprep","studene","bezmasa"]},
{id:"kbv102",n:"Fazuľové Brownie",c:"dezert",p:112,s:3,k:360,pr:22,ca:38,f:12,tm:30,
ing:["1 konzerva červenej fazule (cca 240 g po odkvapkaní)","2 vajíčka","30 g kvalitného holandského kakaa","30 g čokoládového proteínu (alebo viac kakaa a medu)","2 PL medu alebo čakankového sirupu","30 g horkej čokolády (nasekanej na kúsky)"],
st:["Fazuľu dôkladne prepláchni pod tečúcou vodou a osuš ju.","Do stolného mixéra vlož fazuľu, vajíčka, kakao, proteín a med. Rozmixuj na úplne hladké čokoládové cesto.","Cesto vylej do malej zapekacej formy s papierom na pečenie a vrch posyp nasekanou horkou čokoládou.","Peč pri 180 °C asi 20 minút. Vnútri musí ostať mierne vlhké a vláčne.","Po vychladnutí nakrájaj brownie na 3 veľké kusy."],
tip:"Fazuľa nahrádza múku aj maslo – brownie nikdy nevyschne.",t:["mealprep","studene","bezmasa"]},
{id:"kbv103",n:"Kokosové guľky",c:"desiata",p:113,s:3,k:340,pr:18,ca:35,f:14,tm:15,
ing:["250 g hrudkovitého tvarohu","80 g jemných ovsených vločiek","40 g strúhaného kokosu (+ 20 g na obalenie)","2 PL medu alebo agáve sirupu","1 hrsť celých lúpaných mandlí"],
st:["V miske rukami vypracuj cesto z tvarohu, ovsených vločiek, 40 g kokosu a medu. Nechaj 5 minút odpočívať.","Mokrými rukami odoberaj kúsok hmoty, do stredu zatlač jednu mandľu a v dlaniach vygúľaj guľku.","Každú guľku okamžite obaľ vo zvyšnom strúhanom kokose.","Rozdeľ do troch krabičiek a daj zachladiť."],
tip:"Vločky nasajú vlhkosť z tvarohu, takže guľky v chladničke stuhnú.",t:["mealprep","rychle","studene","bezmasa"]},
{id:"kbv104",n:"Sladký bulgur",c:"dezert",p:114,s:3,k:390,pr:15,ca:60,f:8,tm:20,
ing:["150 g bulguru (v suchom stave)","300 ml mlieka (na varenie bulguru)","150 g bieleho gréckeho jogurtu","150 g mrazeného ovocia (lesná zmes)","2 PL javorového sirupu alebo medu","1 ČL škorice"],
st:["Bulgur uvar namiesto vo vode priamo v mlieku (asi 15 minút na miernom ohni). Nechaj chvíľu vychladnúť.","Mrazené ovocie zohrej v malom hrnci alebo mikrovlnke, kým nepustí šťavu, a vmiešaj doň 1 PL sirupu.","K vlažnému bulguru pridaj škoricu, zvyšný sirup a zľahka primiešaj grécky jogurt.","Na dno ulož mliečny bulgur a navrch rozlej horúce lesné ovocie aj so šťavou."],
tip:"Bulgur sa nerozmočí a po zohriatí si udrží perfektnú zrnitú štruktúru.",t:["mealprep","mikrovlnka","bezmasa"]},
{id:"kbv105",n:"Fit Tiramisu",c:"dezert",p:115,s:3,k:370,pr:20,ca:45,f:10,tm:15,
ing:["100 g celozrnných alebo špaldových piškót","1 šálka silného espressa (vychladnutého)","250 g jemného odtučneného tvarohu","100 g bieleho gréckeho jogurtu (alebo light mascarpone)","2 PL medu","1 PL kvalitného kakaa na posypanie"],
st:["V miske dôkladne vymiešaj tvaroh, grécky jogurt a med na hladký krém.","Piškóty na sekundu z oboch strán namoč do studeného espressa a ulož na dno každej nádoby.","Na piškóty rozotri vrstvu tvarohového krému.","Zopakuj ešte raz – vrstva namočených piškót a na ňu zvyšný krém.","Vrch bohato posyp preosiatym kakaom a daj stuhnúť do chladničky."],
tip:"Za 2–3 dni v chladničke kávové piškóty zmäknú do dokonalosti.",t:["mealprep","rychle","studene","bezmasa"]}
];
